// Verse text, keyed by reference id.
var verses = {
    "2CO.5.17": "A tak jeźli kto jest w Chrystusie, nowem jest stworzeniem; stare rzeczy przeminęły, oto się wszystkie nowemi stały.",
    "COL.3.1-2": "A tak jeźliście powstali z Chrystusem, tego, co jest w górze, szukajcie, gdzie Chrystus na prawicy Bożej siedzi; O tem, co jest w górze, myślcie, nie o tem, co jest na ziemi.",
    "ISA.43.2": "Gdy pójdziesz przez wody, będę z tobą, a jeźli przez rzeki, nie zaleją cię; pójdzieszli przez ogień, nie spalisz się, a płomień nie imie się ciebie.",
    "PSA.34.8": "Skosztujcież, a obaczcie, jako jest dobry Pan: błogosławiony człowiek, który w nim ufa.",
    "ROM.15.4": "Bo cokolwiek przedtem napisano, ku naszej nauce napisano, abyśmy przez cierpliwość i przez pociechę Pism nadzieję mieli.",
    "PSA.55.22": "Wrzuć na Pana brzemię twoje, a on cię opatrzy, i nie dopuści, aby się na wieki zachwiać miał sprawiedliwy.",
    "ISA.40.8": "Trawa usycha, kwiat opada; ale słowo Boga naszego trwa na wieki.",
    "PSA.127.1": "Jeźli Pan domu nie zbuduje, próżno pracują ci, którzy go budują; jeźli Pan nie będzie strzegł miasta, próżno czuje ten, który go strzeże.",
    "ISA.53.6": "Wszyscyśmy jako owce zbłądzili, każdy na drogę swą obróciliśmy się, a Pan włożył nań nieprawość wszystkich nas.",
    "PSA.42.1-2": "Jako jeleń krzyczy do strumieni wód, tak dusza moja woła do ciebie, o Boże! Pragnie dusza moja do Boga, do Boga żywego, mówiąc: Kiedyż przyjdę, a okażę się przed obliczem Bożem?",
    "2SA.22.31": "Droga Boża jest doskonała, wyrok Pański nader czysty, tarczą jest wszystkim, którzy w nim ufają.",
    "PSA.40.1-3": "Z żądością oczekiwałem Pana; a skłonił się ku mnie, i wysłuchał wołanie moje; I wyciągnął miecz z dołu szumiącego i z błota lgnącego, a postawił na skale nogi moje, i utwierdził kroki moje; A włożył w usta moje pieśń nową, chwałę należącą Bogu naszemu, co gdy wiele ich ogląda, ulękną się, a będą mieć nadzieję w Panu.",
    "JOB.19.25": "Aczci ja wiem, iż Odkupiciel mój żyje, a iż w ostateczny dzień nad prochem stanie.",
    "PSA.23.1-3": "Pan jest pasterzem moim, na niczem mi nie zejdzie. Na paszach zielonych postawił mię; a do wód cichych prowadzi mię. Duszę moję posila: prowadzi mię ścieszkami sprawiedliwości dla imienia swego.",
    "MAT.5.44": "Aleć Ja wam powiadam: Miłujcie nieprzyjacioły wasze; błogosławcie tym, którzy was przeklinają; dobrze czyńcie tym, którzy was mają w nienawiści, i módlcie się za tymi, którzy wam złość wyrządzają i prześladują was;",
    "ISA.55.8-9": "Boć zaiste myśli moje nie są jako myśli wasze, ani drogi wasze jako drogi moje, mówi Pan; Ale jako wyższe są niebiosa niż ziemia, tak przewyższają drogi moje drogi wasze, a myśli moje myśli wasze.",
    "LUK.19.10": "Bo przyszedł Syn człowieczy, aby szukał i zachował, co było zginęło.",
    "HEB.13.5-6": "Obcowanie wasze niech będzie bez łakomstwa, przestwając na tem, co macie; boć sam powiedział: Nie zaniecham cię, ani cię opuszczę: Tak abyśmy śmiele mówić mogli: Pan mi jest pomocnikiem, nie będę się bał, aby mi co miał uczynić człowiek.",
    "1CH.29.11": "Twoja jest, Panie! wielmożność, i moc, i sława, i zwyciąstwo, i cześć, i wszystko na niebie i na ziemi; twoje jest, Panie! królestwo, a tyśjest wywższony nad wszelką zwierzchność.",
    "HEB.13.20-21": "A Bóg pokoju, który wywiódł od umarłych we krwi przymierza wiecznego, onego wielkiego pasterza owiec, Pana naszego Jezusa, Niech was doskonałymi uczyni w każdym uczynku dobrym ku czynieniu woli swojej, sprawując w was to, co przyjemnego przed obliczem jego, przez Jezusa Chrystusa, któremu niech będzie chwała na wieki wieków. Amen.",
    "1CO.1.18": "Albowiem mowa o krzyżu tym, którzy giną, jest głupstwem; ale nam, którzy bywamy zbawieni, jest mocą Bożą.",
    "MAT.5.14-16": "Wy jesteście światłość świata, nie może się miasto ukryć na górze leżące. Ani zapalają świecy, i stawiają jej pod korzec, ale na świecznik, i świeci wszystkim, którzy są w domu. Tak niechaj świeci światłość wasza przed ludźmi, aby uczynki wasze dobre widzieli, a chwalili ojca waszego, który jest w niebiesiech.",
    "COL.3.23-24": "A wszystko, cokolwiek czynicie, z duszy czyńcie, jako Panu, a nie ludziom. Wiedząc, iż od Pana weźmiecie zapłatę dziedzictwa; albowiem Panu Chrystusowi służycie.",
    "ROM.8.28": "A wiemy, iż tym, którzy miłują Boga, wszystkie rzeczy dopomagają ku dobremu, to jest tym, którzy według postanowienia Bożego powołani są.",
    "JHN.11.25-26": "I rzekł jej Jezus: Jam jest zmartwychwstanie i żywot; kto w mię wierzy, choćby też umarł, żyć będzie. A wszelki, który żyje, a wierzy w mię, nie umrze na wieki. Wierzyszże temu?",
    "1CO.13.6-7": "Nie raduje się z niesprawiedliwości, ale się raduje z prawdy; Wszystko okrywa, wszystkiemu wierzy, wszystkiego się spodziewa, wszystko cierpi.",
    "MAT.7.12": "Wszystko tedy, co byście chcieli, aby wam ludzie czynili, tak i wy czyńcie im; tenci bowiem jest zakon i prorocy.",
    "PSA.91.11": "Albowiem Aniołom swoim przykazał o tobie, aby cię strzegli na wszystkich drogach twoich.",
    "ACT.2.38": "Tedy Piotr rzekł do nich: Pokutujcie, a ochrzcij się każdy z was w imieniu Jezusa Chrystusa na odpuszczenie grzechów, a weźmiecie dar Ducha Świętego.",
    "1CO.3.16": "Azaż nie wiecie, iż kościołem Bożym jesteście, a Duch Boży mieszka w was?",
    "ROM.3.23-24": "Albowiem wszyscy zgrzeszyli i nie dostaje im chwały Bożej. A bywają usprawiedliwieni darmo z łaski jego przez odkupienie, które się stało w Chrystusie Jezusie.",
    "MAT.5.6": "Błogosławieni, którzy łakną i pragną sprawiedliwości; albowiem oni nasyceni będą.",
    "ISA.26.3": "Człowieka spolegającego na tobie zachowywasz w pokoju, w pokoju mówię: bo w tobie ufa.",
    "PRO.17.22": "Serce wesołe oczerstwia jako lekarstwo; ale duch sfrasowany wysusza kości.",
    "NEH.8.10": "I rzekł im: Idźcież, jedzcie rzeczy tłuste a pijcie napój słodki, a posyłajcie cząstki tym, którzy sobie nic nie nagotowali; albowiem święty jest dzień Panu naszemu. Przetoż się nie frasujcie; albowiem wesele Pańskie jest siłą waszą,",
    "1PE.2.9": "Ale wy jesteście rodzajem wybranym, królewskim kapłaństwem, narodem świętym, ludem nabytym, abyście opowiadali cnoty tego, który was powołał z ciemności ku dziwnej swojej światłości.",
    "PSA.18.2": "Pan opoką moją, twierdzą moją, i wybawicielem moim; Bóg mój skała moja, w nim będę ufał; tarcza moja, i róg zbawienia mego, ucieczka moja.",
    "1CO.15.58": "A tak, bracia moi mili! bądźcie mocni, nieporuszeni, obfitujący w uczynku Pańskim zawsze, wiedząc, iż praca wasza nie jest nadaremna w Panu.",
    "EXO.14.14": "Pan będzie walczył za was, a wy milczeć będziecie.",
    "2CH.15.7": "Przetoż wy zmacniajcie się, a niech nie słabieją ręce wasze; bo czeka zapłata pracy waszej.",
    "PHP.4.11-12": "Nie żebym to mówił dla niedostatku; bomci się ja nauczył, na tem przestawać, co mam. Umiem i uniżać się, umiem i obfitować; wszędy i we wszystkich rzeczach jestem wyćwiczony i nasyconym być, i łaknąć, i obfitować, i niedostatek cierpieć;",
    "ISA.58.11": "Bo cię Pan ustawicznie poprowadzi, i nasyci pod największą suszą duszę twoję, a kości twoje utuczy, i będziesz jako ogród wilgotny, a jako zdrój wód, którego wody nie ustawają.",
    "MAT.16.24": "Tedy rzekł Jezus do uczniów swoich: Jeźli kto chce iść za mną, niechajże samego siebie zaprze, a weźmie krzyż swój, i naśladuje mię!",
    "DEU.31.6": "Zmacniajcież się, a mężnie sobie poczynajcie, nie bójcie się, ani się lękajcie twarzy ich; albowiem Pan, Bóg twój, on idzie z tobą, nie odstąpi cię, ani cię opuści.",
    "1CO.13.4-5": "Miłość jest długo cierpliwa, dobrotliwa jest; miłość nie zajrzy, miłość nie jest rozpustna, nie nadyma się; Nie czyni nic nieprzystojnego, nie szuka swoich rzeczy, nie jest porywcza do gniewu, nie myśli złego;",
    "ACT.16.31": "A oni rzekli: Wierz w Pana Jezusa Chrystusa, a będziesz zbawiony, ty i dom twój.",
    "1PE.4.10": "Każdy jako wziął dar, tak nim jeden drugiemu usługujcie, jako dobrzy szafarze rozlicznej łaski Bożej.",
    "PSA.46.1": "Bóg jest ucieczką i siłą naszą, ratunkiem we wszelkim ucisku najpewniejszym.",
    "ISA.41.13": "Bom ja Pan, Bóg twój, trzymam cię za prawicę twoję, a mówięć: Nie bój się! Ja cię wspomogę.",
    "1CO.15.3-4": "Albowiem naprzód podałem wam, com też wziął, iż Chrystus umarł za grzechy nasze według Pism; A iż był pogrzebiony, a iż zmartwychwstał dnia trzeciego według Pism.",
    "JER.17.7-8": "Błogosławiony mąż, który ufa w Panu, a Pan jest nadzieją jego. Bo będzie jako drzewo wszczepione nad wodami, a nad strumieniem zapuszczające korzenie swoje, które nie czuje, gdy przychodzi gorącość, ale liść jego zostaje zielony, a roku suchego nie frasuje się, i nie przestaje przynosić owocu.",
    "PHP.1.6": "Pewien tego będąc, iż ten, który począł w was dobrą sprawę, dokona aż do dnia Jezusa Chrystusa.",
    "2CO.12.9": "Ale mi rzekł: Dosyć masz na łasce mojej; albowiem moc moja wykonywa się w słabości. Raczej się tedy więcej chlubić będę z krewkości moich, aby we mnie mieszkała moc Chrystusowa.",
    "HEB.4.15-16": "Albowiem nie mamy najwyższego kapłana, który by nie mógł z nami cierpieć krewkości naszych, lecz skuszonego we wszystkiem na podobieństwo nas, oprócz grzechu. Przystąpmyż tedy z ufnością do tronu łaski, abyśmy dostąpili miłosierdzia i łaskę znaleźli ku pomocy czasu przygodnego.",
    "PRO.4.23": "Nad wszystko, czego ludzie strzegą, strzeż serca twego; bo z niego żywot pochodzi.",
    "ROM.11.33": "O głębokości bogactwa i mądrości, i znajomości Bożej! Jako są niewybadane sądy jego i niedoścignione drogi jego!",
    "JHN.1.1-3": "Na początku było Słowo, a ono Słowo było u Boga, a Bogiem było ono Słowo. To było na początku u Boga. Wszystkie rzeczy przez nie się stały, a bez niego nic się nie stało, co się stało.",
    "PSA.56.3-4": "Któregokolwiek mię dnia strach ogarnia, ja w tobie ufam. Boga wysławiać będę dla słowa jego; w Bogu nadzieję będę miał, ani się będę bał, żeby mi co ciało uczynić mogło.",
    "JHN.10.11": "Jam jest on dobry pasterz; dobry pasterz duszę swoję kładzie za owce.",
    "ROM.12.21": "Nie daj się zwyciężyć złemu, ale złe dobrem zwyciężaj.",
    "MRK.9.23": "Ale mu Jezus rzekł: Jeźli możesz temu wierzyć? Wszystko jest możno wierzącemu.",
    "DEU.33.27": "Mieszkaniem twojem Bóg wieczny, a ze spodku ramiona wieczności. Ten wyrzuci przed tobą nieprzyjaciela, a rzeczeć: Wytrać go;",
    "PRO.17.17": "Wszelkiego czasu miłuje przyjaciel, a w ucisku stawia się jako brat.",
    "PSA.19.1": "Niebiosa opowiadają chwałę Bożą, a dzieło rąk jego rozpostarcie oznajmuje.",
    "MAL.3.10": "Znieście wszystkę dziesięcinę do szpichleża, aby była żywność w domu moim, a doświadczcie mię teraz w tem, mówi Pan zastępów; jeźli wam nie otworzę okien niebieskich, a nie wyleję na was błogosławieństwa, tak że go nie będziecie mieli gdzie podziać;",
    "JOS.24.15": "A jeźli się wam zda źle służyć Panu, obierzcież sobie dziś, komu byście służyli, chociaż bogi, którym służyli ojcowie wasi, co byli za rzeką, chociaż bogi Amorejskie, w których wy ziemi mieszkacie; aleć ja i dom mój będziemy służyli Panu.",
    "ECC.12.13": "Suma wszystkiego, coś słyszał: Boga się bój, a przykazań jego przestrzegaj, bo na tem człowiekowi wszystko zależy;",
    "PSA.37.23-24": "Od Pana bywają sprawowane drogi człowieka dobrego, a droga jego, podoba mu się. Gdy padnie, nie stłucze się: albowiem Pan trzyma go za rękę jego.",
    "REV.21.5": "I rzekł ten, który siedział na stolicy: Oto wszystko nowe czynię. I rzekł mi: Napisz: bo te słowa są wierne i prawdziwe.",
    "ISA.40.31": "Ale którzy oczekują Pana, nabywają nowej siły; podnoszą się piórami jako orły, bieżą a nie spracują się, chodzą a nie ustawają.",
    "JHN.4.13-14": "Odpowiedział Jezus i rzekł jej: Każdy, kto pije tę wodę, zasię będzie pragnął; Lecz kto by pił onę wodę, którą ja mu dam, nie będzie pragnął na wieki; ale ta woda, którą ja mu dam, stanie się w nim studnią wody wyskakującej ku żywotowi wiecznemu.",
    "HEB.12.1-2": "Przetoż i my, mając tak wielki około siebie leżący obłok świadków, złożywszy wszelaki ciężar i grzech, który nas snadnie obstępuje, przez cierpliwość bieżmy w zawodzie, który nam jest wystawiony; Patrząc na Jezusa, wodza i dokończyciela wiary, który dla wystawionej sobie radości, podjął krzyż, wzgardziwszy sromotę, i usiadł na prawicy stolicy Bożej.",
    "1JN.4.18": "Nie maszci bojaźni w miłości, ale miłość doskonała precz wyrzuca bojaźń: bo bojaźń ma udręczenie, a kto się boi, nie jest doskonały w miłości.",
    "PSA.118.24": "Tenci to dzień, który uczynił Pan; rozweselmyż się, a rozradujmy się weń.",
    "HEB.12.11": "A wszelkie karanie, gdy przytomne jest, nie zda się być wesołe, ale smutne; lecz potem owoc sprawiedliwości spokojny przynosi tym, którzy są przez nie wyćwiczeni.",
    "ECC.4.9-10": "Lepiej jest we dwóch być, niż jednemu; mają zaiste dobry pożytek z pracy swojej. Bo jeźli jeden upadnie, drugi podźwignie towarzysza swego. A tak biada samotnemu, gdyby upadł! bo nie ma drugiego, coby go podźwignął.",
    "2CO.1.3-4": "Błogosławiony niech będzie Bóg i Ojciec Pana naszego, Jezusa Chrystusa, Ojciec miłosierdzia a Bóg wszelkiej pociechy, Który nas cieszy w każdym ucisku naszym, abyśmy i my cieszyć mogli i tych, którzy są w jakimkolwiek ucisku, tąż pociechą, którą my sami pocieszeni bywamy od Boga.",
    "PSA.30.5": "Albowiem prędko przemija gniew jego, ale po wszystek żywot trwa dobra wola jego; z wieczora bywa płacz, ale z poranku wesele.",
    "GAL.6.2": "Jedni drugich brzemiona noście, a tak wypełniajcie zakon Chrystusowy.",
    "JHN.14.27": "Pokój zostawuję wam, pokój on mój daję wam; nie jako daje świat, ja wam daję; niechże się nie trwoży serce wasze, ani się lęka.",
    "GAL.3.26-28": "Albowiem wszyscy synami Bożymi jesteście przez wiarę w Chrystusie Jezusie. Bo którzykolwiek jesteście w Chrystusa ochrzczeni, w Chrystusaście się oblekli. Nie masz Żyda, ani Greka; nie masz niewolnika ani wolnego; nie masz mężczyzny i niewiasty; albowiem wszyscy wy jednym jesteście w Chrystusie Jezusie.",
    "EXO.33.14": "I odpowiedział Pan: Oblicze moje pójdzie przed tobą, a dam ci odpocznienie.",
    "LUK.1.37": "Bo nie będzie niemożne u Boga żadne słowo.",
    "PRO.16.3": "Włóż na Pana sprawy twe, a będą utwierdzone zamysły twoje.",
    "ACT.17.27-28": "Aby szukali Pana, owaby go snać namacali i znaleźli, aczkolwiek od każdego z nas nie jest daleko. Albowiem w nim żyjemy i ruszamy się, i jesteśmy, jako i niektórzy z waszych poetów powiedzieli: Żeśmy i my rodziną jego.",
    "JHN.5.24": "Zaprawdę, zaprawdę powiadam wam: Kto słowa mego słucha i wierzy onemu, który mię posłał, ma żywot wieczny i nie przyjdzie na sąd, ale przeszedł z śmierci do żywota.",
    "MRK.1.15": "A mówiąc: Wypełnił się czas i przybliżyło się królestwo Boże: Pokutujcie, a wierzcie Ewangielii.",
    "PRO.16.9": "Serce człowiecze rozrządza drogi swe; ale Pan sprawuje kroki jego.",
    "PSA.46.10": "Mówiąc: Uspokójcie się, a wiedzcie, żem Ja Bóg; będę wywyższony między narodami, będę wywyższony na ziemi.",
    "2TH.3.16": "A sam Pan pokoju niech wam da pokój zawsze i wszelkim sposobem. Pan niech będzie z wami wszystkimi.",
    "1TH.5.16-18": "Zawsze się radujcie. Bez przestanku się módlcie. Za wszystko dziękujcie; albowiem tać jest wola Boża w Chrystusie Jezusie przeciwko wam.",
    "PHP.3.13-14": "Bracia! jać o sobie nie rozumiem, żebym już uchwycił. Ale jedno czynię, że tego, co za mną jest, zapamiętywając, a do tego się, co przede mną jest, spiesząc, bieżę do kresu ku zakładowi powołania onego Bożego, które jest z góry w Chrystusie Jezusie.",
    "MAT.24.35": "Niebo i ziemia przeminą, ale słowa moje nie przeminą.",
    "EPH.5.1-2": "Bądźcież tedy naśladowcami Bożymi, jako dzieci miłe; A chodźcie w miłości, jako i Chrystus umiłował nas i wydał samego siebie na ofiarę i na zabicie Bogu ku wdzięcznej wonności.",
    "PRO.18.10": "Imię Pańskie jest mocną wieżą; sprawiedliwy się do niej uciecze, a wywyższony będzie.",
    "JHN.15.4-5": "Mieszkajcież we mnie, a ja w was; jako latorośl nie może przynosić owocu sama z siebie, jeźli nie będzie trwała w winnej macicy, także ani wy, jeźli we mnie mieszkać nie będziecie. Jam jest winna macica, a wyście latorośle; kto mieszka we mnie, a ja w nim, ten przynosi wiele owocu; bo beze mnie nic uczynić nie możecie.",
    "PSA.37.4": "Kochaj się w Panu, a dać prośby serca twego,",
    "1JN.4.9-10": "Przez to objawiona jest miłość Boża ku nam, iż Syna swego jednorodzonego posłał Bóg na świat, abyśmy żyli przez niego. W tem jest miłość, nie iżbyśmy my umiłowali Boga, ale iż on umiłował nas i posłał Syna swego, aby był ubłaganiem za grzechy nasze.",
    "JHN.17.3": "A toć jest żywot wieczny, aby cię poznali samego prawdziwego Boga, i któregoś posłał, Jezusa Chrystusa.",
    "2CO.4.6": "Ponieważ Bóg, który rzekł, aby się z ciemności światłość rozświeciła, ten się rozświecił w sercach naszych ku rozświeceniu (w nas) znajomości chwały Bożej w obliczu Jezusa Chrystusa.",
    "COL.3.12-13": "Przetoż przyobleczcie jako wybrani Boży, święci i umiłowani, wnętrzności miłosierdzia, dobrotliwość, pokorę, cichość, cierpliwość, Znaszając jedni drugich i odpuszczając sobie wzajemnie, jeźli ma kto przeciw komu skargę: jako i Chrystus odpuścił wam, tak i wy.",
    "PSA.1.1-2": "Błogosławiony mąż, który nie chodzi w radzie niepobożnych, a na drodze grzesznych nie stoi, i na stolicy naśniewców nie siedzi; Ale w zakonie Pańskim jest kochanie jego, a w zakonie jego rozmyśla we dnie i w nocy.",
    "PRO.3.11-12": "Synu mój! karania Pańskiego nie odrzucaj, i nie uprzykrzaj sobie ćwiczenia jego. Bo kogo Pan miłuje, tego karze, a to jako ojciec, który się w synu kocha.",
    "ECC.3.11": "Wszystko dobrze czyni czasu swego; owszem i żądość świata dał do serca ich, choć człowiek dzieła tego, które Bóg sprawuje, ani początku, ani końca nie dochodzi.",
    "JOL.2.13": "Rozedrzyjcie serce wasze a nie szaty wasze, i nawróćcie się do Pana, Boga waszego; boć on jest łaskawy i miłosierny, nierychły ku gniewu, a hojny w miłosierdziu, i żałujący złego.",
    "GAL.6.9-10": "A dobrze czyniąc nie słabiejmy; albowiem czasu swojego żąć będziemy nie ustawając. Przeto tedy, póki czas mamy, dobrze czyńmy wszystkim, a najwięcej domownikom wiary.",
    "PSA.136.1": "Wysławiajcież Pana, albowiem jest dobry; albowiem na wieki miłosierdzie jego.",
    "PHP.4.13": "Wszystko mogę w Chrystusie, który mię posila.",
    "EPH.4.32": "A bądźcie jedni przeciwko drugim dobrotliwi, miłosierni, odpuszczając sobie, jako wam Bóg w Chrystusie odpuścił.",
    "JAS.1.12": "Błogosławiony mąż, który znosi pokuszenie; bo gdy będzie doświadczony, weźmie koronę żywota, którą obiecał Pan tym, którzy go miłują.",
    "JHN.1.12": "Lecz którzykolwiek go przyjęli, dał im tę moc, aby się stali synami Bożymi, to jest tym, którzy wierzą w imię jego.",
    "EPH.3.17-19": "Aby Chrystus przez wiarę mieszkał w sercach waszych; Żebyście w miłości wkorzenieni i ugruntowani będąc, mogli doścignąć ze wszystkimi świętymi, która jest szerokość i długość, i głębokość, i wysokość; I poznać miłość Chrystusową przewyższającą wszelką znajomość, abyście napełnieni byli wszelaką zupełnością Bożą.",
    "PHP.2.9-11": "Dlatego też Bóg nader go wywyższył i darował mu imię, które jest nad wszystkie imię; Aby w imieniu Jezusowem wszelkie się kolano skłaniało, tych, którzy są na niebiesiech i tych, którzy są na ziemi, i tych, którzy są pod ziemią. A wszelki język aby wyznawał, że Jezus Chrystus jest Panem ku chwale Boga Ojca.",
    "PRO.31.30": "Omylna jest wdzięczność, i marna piękność; ale niewiasta, która się Pana boi, ta pochwały godna.",
    "MAT.28.19-20": "Idąc tedy, nauczajcie wszystkie narody, chrzcząc je w imię Ojca, i Syna, i Ducha Świętego; Ucząc je przestrzegać wszystkiego, com wam przykazał. A oto Jam jest z wami po wszystkie dni, aż do skończenia świata. Amen.",
    "1JN.3.16": "Przez tośmy poznali miłość Bożą, iż on duszę swoję za nas położył; i myśmy powinni kłaść duszę za braci.",
    "EPH.4.1-3": "Proszę was tedy ja więzień w Panu, abyście chodzili tak, jako przystoi na powołanie, którem jesteście powołani; Ze wszelaką pokorą i cichością, i z nieskwapliwością, znosząc jedni drugich w miłości, Starając się, abyście zachowali jedność ducha w związce pokoju.",
    "PSA.100.4-5": "Wnijdźcież w bramy jego z wysławianiem, a do sieni jego z chwałami; wysławiajcież go, dobrorzeczcież imieniowi jego; Albowiem dobry jest Pan, na wieki trwa miłosierdzie jego, a od narodu aż do narodu prawda jego.",
    "HAB.3.17-18": "Choćby figowe drzewo nie zakwitnęło i nie było urodzaju na winnicach, choćby i owoc oliwy pochybił, i role nie przyniosłyby pożytku, i z owczarniby owce wybite były, a nie byłoby bydła w oborach; Wszakże się ja w Panu weselić będę, rozraduję się w Bogu zbawienia mego.",
    "ROM.6.23": "Albowiem zapłata za grzech jest śmierć; ale dar z łaski Bożej jest żywot wieczny, w Chrystusie Jezusie, Panu naszym.",
    "LAM.3.22-23": "Wielkie jest miłosierdzie Pańskie, żeśmy do szczętu nie zginęli; nie ustawają zaiste litości jego. Ale się na każdy poranek odnawiają; wielka jest prawda twoja.",
    "1JN.3.1": "Patrzcie, jaką miłość dał nam Ojciec, abyśmy dziatkami Bożemi nazwani byli. Dlategoć świat nie zna nas, iż onego nie zna.",
    "PSA.150.6": "Niech wszelki duch chwali Pana! Halleluja.",
    "2CO.4.16-18": "Dlatego nie słabiejmy, ale choć się też nasz zewnętrzny człowiek kazi, wszakże on wewnętrzny się odnawia ode dnia do dnia. Albowiem ten króciuchny i lekki ucisk nasz nader zacnej chwały wieczną wagę nam sprawuje; Gdy nie patrzymy na rzeczy widzialne, ale na niewidzialne; albowiem rzeczy widzialne są doczesne, ale niewidzialne są wieczne.",
    "JER.29.12-13": "Gdy mię wzywać będziecie, a pójdziecie, i modlić mi się będziecie, tedy was wysłucham; A szukając mię, znajdziecie; gdy mię szukać będziecie ze wszystkiego serca swego,",
    "REV.21.4": "I otrze Bóg wszelką łzę z oczów ich; a śmierci więcej nie będzie, ani smutku, ani krzyku, ani boleści nie będzie; albowiem pierwsze rzeczy pominęły.",
    "PSA.84.11": "Albowiem Pan Bóg jest słońcem i tarczą: tuć łaski i chwały Pan udziela, i nie odmawia, co jest dobrego, tym, którzy chodzą w niewinności.",
    "1TI.6.12": "Bojuj on dobry bój wiary, chwyć się żywota wiecznego, do któregoś też powołany, i wyznałeś dobre wyznanie przed wieloma świadkami.",
    "LAM.3.25-26": "Dobry jest Pan tym, którzy nań oczekują, duszy takowej, która go szuka. Dobrze jest, cierpliwie oczekiwać na zbawienie Pańskie.",
    "2CO.3.17": "Aleć Pan jest tym Duchem; a gdzie jest ten Duch Pański, tam i wolność.",
    "PSA.91.1-2": "Ten, który mieszka w ochronie Najwyższego, i w cieniu Wszechmocnego przebywać będzie; Rzecze Panu: Nadzieja moja i zamek mój, Bóg mój, w nim nadzieję mieć będę.",
    "EPH.1.3": "Błogosławiony niech będzie Bóg i Ojciec Pana naszego Jezusa Chrystusa, który nas ubłogosławił wszelkiem błogosławieństwem duchownem w niebieskich rzeczach w Chrystusie;",
    "MAT.4.4": "A on odpowiadając rzekł: Napisano: Nie samym chlebem człowiek żyć będzie, ale każdem słowem pochodzącem przez usta Boże.",
    "ISA.49.15-16": "Izali może zapomnieć niewiasta niemowlątka swego, aby się nie zlitowała nad płodem żywota swego? A choćby też i one zapomniały, wszakże Ja ciebie nie zapomnę. Oto na dłoniach swoich wyrysowałem cię; mury twoje zawżdy są przedemną.",
    "HEB.10.24-25": "I przypatrujmy się jedni drugim ku pobudzaniu się do miłości i do dobrych uczynków, Nie opuszczając społecznego zgromadzenia naszego, jako niektórzy obyczaj mają, ale napominając jedni drugich, a to tem więcej, czem więcej widzicie, iż się on dzień przybliża.",
    "ROM.1.16": "Albowiem nie wstydzę się za Ewangieliję Chrystusową, ponieważ jest mocą Bożą ku zbawieniu każdemu wierzącemu, Żydowi najprzód, potem i Greczynowi.",
    "2TI.1.7": "Albowiem nie dał nam Bóg Ducha bojaźni, ale mocy i miłości, i zdrowego zmysłu.",
    "ISA.40.28-29": "Izali nie wiesz? izaliś nie słyszał, że Bóg wieczny Pan, który stworzył granice ziemi, nie ustanie, ani się spracuje, i że nie może być dościgniona mądrość jego? Który dodaje spracowanemu siły, a tego, który nie ma żadnej siły, moc rozmnaża.",
    "JHN.8.31-32": "Tedy mówił Jezus do tych Żydów, co mu uwierzyli: Jeźli wy zostaniecie w słowie mojem, prawdziwie uczniami moimi będziecie; Poznacie prawdę, a prawda was wyswobodzi.",
    "HEB.11.1": "A wiara jest gruntem tych rzeczy, których się spodziewamy i dowodem rzeczy niewidzialnych.",
    "ISA.40.11": "Jako pasterz trzodę swoję paść będzie; do naręcza swego zgromadzi baranki, i na łonie swem piastować je będzie, a kotne zwolna poprowadzi.",
    "JHN.13.34-35": "Przykazanie nowe daję wam, abyście się społecznie miłowali; jakom i ja was umiłował, abyście się i wy społecznie miłowali. Stądci poznają wszyscy, żeście uczniami moimi, jeźli miłość mieć będziecie jedni przeciwko drugim.",
    "JER.1.5": "Pierwej niżelim cię utworzył w żywocie, znałem cię, a pierwej niżeliś wyszedł z żywota, poświęciłem cię, za proroka narodom dałem cię.",
    "EPH.4.29": "Żadna mowa plugawa niech z ust waszych nie pochodzi; ale jeźli która jest dobra ku potrzebnemu zbudowaniu, aby była przyjemna słuchającym.",
    "JHN.10.10": "Złodziej nie przychodzi, jedno żeby kradł, a zabijał i tracił; jam przyszedł, aby żywot miały, i obficie miały.",
    "HEB.11.6": "A bez wiary nie można podobać się Bogu; albowiem ten, co przystępuje do Boga, wierzyć musi, że jest Bóg, a że nagrodę daje tym, którzy go szukają.",
    "ISA.55.6-7": "Szukajcie Pana, póki może być znaleziony; wzywajcie go, póki blisko jest. Niech opuści niepobożny drogę swoję, a człowiek nieprawy myśli swoje i niech się nawróci do Pana, a zmiłuje się; i do Boga naszego, gdyż jest hojnym w odpuszczaniu.",
    "JHN.15.16": "Nie wyście mnie obrali, alem ja was obrał; i postanowiłem, abyście wyszli i przynieśli owoc, a owoc wasz aby trwał, i o cokolwiek byście prosili Ojca w imieniu mojem, żeby wam dał.",
    "1CO.13.13": "A teraz zostaje wiara, nadzieja, miłość, te trzy rzeczy; lecz z nich największa jest miłość.",
    "ROM.8.38-39": "Albowiem pewienem tego, iż ani śmierć, ani żywot, ani Aniołowie, ani księstwa, ani mocarstwa, ani teraźniejsze ani przyszłe rzeczy, Ani wysokość, ani głębokość, ani żadne insze stworzenie nie będzie nas mogło odłączyć od miłości Bożej, która jest w Jezusie Chrystusie, Panu naszym.",
    "MAT.6.26": "Spojrzyjcie na ptaki niebieskie, iż nie sieją ani żną, ani zbierają do gumien, a wżdy Ojciec wasz niebieski żywi je; izali wy nie jesteście daleko zacniejsi nad nie?",
    "1TI.1.15": "Wierna jest ta mowa i wszelkiego przyjęcia godna, iż Chrystus Jezus przyszedł na świat, aby grzeszników zbawił, z których jam jest pierwszy.",
    "JAS.1.22": "A bądźcie czynicielami słowa, a nie słuchaczami tylko, oszukiwającymi samych siebie.",
    "PSA.145.18": "Bliski jest Pan wszystkim, którzy go wzywają, wszystkim, którzy go wzywają w prawdzie.",
    "MAT.22.37-39": "A Jezus mu rzekł: Będziesz miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej i ze wszystkiej myśli twojej. To jest pierwsze i największe przykazanie. A wtóre podobne jest temuż: Będziesz miłował bliźniego twego, jako samego siebie.",
    "PSA.16.11": "Oznajmisz mi drogę żywota; obfitość wesela jest przed obliczem twojem, rozkoszy po prawicy twojej aż na wieki.",
    "GEN.1.1": "Na początku stworzył Bóg niebo i ziemię.",
    "JAS.1.5": "A jeźli komu z was schodzi na mądrości, niech prosi u Boga, który ją szczerze wszystkim daje, a nie wymawia; i będzie mu dana.",
    "MAT.18.20": "Albowiem gdzie są dwaj albo trzej zgromadzeni w imię moje, tam jestem w pośrodku ich.",
    "PSA.121.1-2": "Oczy moje podnoszę na góry, skądby mi pomoc przyszła. Pomoc moja jest od Pana, który stworzył niebo i ziemię.",
    "GAL.5.22-23": "Ale owoc Ducha jest miłość, wesele, pokój, nieskwapliwość, dobrotliwość, dobroć, wiara, cichość, wstrzemięźliwość. Przeciwko takowym nie masz zakonu.",
    "ISA.64.8": "Ale teraz, o Panie! tyś jest ojciec nasz, myśmy glina, a tyś twórca nasz; a takeśmy wszyscy dziełem ręki twojej.",
    "ROM.10.13": "Każdy bowiem, kto by wzywał imienia Pańskiego, zbawiony będzie.",
    "COL.3.17": "A wszystko, cokolwiek czynicie w słowie albo w uczynku, wszystko czyńcie w imieniu Pana Jezusa, dziękując Bogu i Ojcu przezeń.",
    "MAT.7.7-8": "Proście, a będzie wam dano, szukajcie, a znajdziecie; kołaczcie, a będzie wam otworzono. Każdy bowiem, kto prosi, bierze; a kto szuka, znajduje; a temu, co kołacze, będzie otworzono.",
    "JHN.20.29": "Rzekł mu Jezus: Żeś mię ujrzał, Tomaszu, uwierzyłeś; błogosławieni którzy nie widzieli, a uwierzyli.",
    "JER.33.3": "Wołaj do mnie, a ozwęć się i oznajmięć rzeczy wielkie i skryte, o których nie wiesz.",
    "EZK.36.26": "I dam wam serce nowe, a ducha nowego dam do wnętrzności waszych, i odejmę serce kamienne z ciała waszego, a dam wam serce mięsiste.",
    "ROM.5.8": "Lecz zaleca Bóg miłość swoję ku nam, że gdy jeszcze byliśmy grzesznymi, Chrystus za nas umarł.",
    "PSA.119.105": "Słowo twe jest pochodnią nogą moim, a światłością ścieszce mojej.",
    "ROM.12.1-2": "Proszę was tedy, bracia! przez litości Boże, abyście stawiali ciała wasze ofiarą żywą, świętą, przyjemną Bogu, to jest rozumną służbę waszę. A nie przypodobywajcie się temu światu, ale się przemieńcie przez odnowienie umysłu waszego na to, abyście doświadczyli, która jest wola Boża dobra, przyjemna i doskonała.",
    "PSA.119.11": "W sercu mojem składam wyroki twoje, abym nie zgrzeszył przeciwko tobie.",
    "1CO.16.13-14": "Czujcież, stójcie w wierze, mężnie sobie poczynajcie, zmacniajcie się. Wszystkie rzeczy wasze niech się dzieją w miłości.",
    "MAT.11.28-30": "Pójdźcie do mnie wszyscy, którzyście spracowani i obciążeni, a Ja wam sprawię odpocznienie; Weźmijcie jarzmo moje na się, a uczcie się ode mnie, żem Ja cichy i pokornego serca; a znajdziecie odpocznienie duszom waszym; Albowiem jarzmo moje wdzięczne jest, a brzemię moje lekkie jest.",
    "1SA.16.7": "Lecz rzekł Pan do Samuela: Nie patrz na urodę jego, ani na wysokość wzrostu jego, gdyżem go odrzucił. Albowiem Ja nie patrzę na to, na co patrzy człowiek; bo człowiek patrzy na to, co jest przed oczyma, ale Pan patrzy na serce.",
    "LUK.1.46-47": "Tedy rzekła Maryja: Wielbi dusza moja Pana; I rozradował się duch mój w Bogu, zbawicielu moim,",
    "GEN.1.27": "Stworzył tedy Bóg człowieka na wyobrażenie swoje; na wyobrażenie Boże stworzył go; mężczyznę i niewiastę stworzył je.",
    "GAL.2.20": "Z Chrystusem jestem ukrzyżowany, a żyję już nie ja, lecz żyje we mnie Chrystus; a to że teraz w ciele żyję, w wierze Syna Bożego żyję, który mię umiłował i wydał samego siebie za mię.",
    "1CO.2.9": "Ale opowiadamy, jako napisano: Czego oko nie widziało i ucho nie słyszało i na serce ludzkie nie wstąpiło, co nagotował Bóg tym, którzy go miłują.",
    "COL.3.16": "Słowo Chrystusowe niechaj mieszka w was obficie ze wszelką mądrością, nauczając i napominając samych siebie przez psalmy i hymny, i pieśni duchowne, wdzięcznie śpiewając w sercach waszych Panu.",
    "NUM.6.24-26": "Niech ci błogosławi Pan, a niechaj cię strzeże; Niech rozjaśni Pan oblicze swoje nad tobą, a niech ci miłościw będzie; Niech obróci Pan twarz swoję ku tobie, a niechaj ci da pokój.",
    "LUK.11.28": "Ale on rzekł: Owszem błogosławieni są, którzy słuchają słowa Bożego i strzegą go.",
    "PSA.63.1": "Boże! tyś jest Bogiem moim; z poranku cię szukam; pragnie cię dusza moja, tęskni po tobie ciało moje w ziemi suchej i upragnionej, w której nie masz wody;",
    "JHN.8.36": "A przetoż jeźli was Syn wyswobodzi, prawdziwie wolnymi będziecie.",
    "PRO.15.1": "Odpowiedź łagodna uśmierza gniew; ale słowa przykre wzruszają popędliwość.",
    "ISA.43.18-19": "Nie wspominajcie pierwszych rzeczy, a starodawnych nie uważajcie. Oto Ja czynię rzecz nową, a zaraz się zjawi; izali tego nie poznacie Nadto sposobię na puszczy drogę, a na pustyni rzeki.",
    "JAS.1.19-20": "A tak, bracia moi mili! niech będzie każdy człowiek prędki ku słuchaniu, ale nierychły ku mówieniu i nierychły ku gniewowi. Bo gniew męża nie sprawuje sprawiedliwości Bożej.",
    "EPH.2.10": "Albowiem czynem jego jesteśmy stworzeni w Chrystusie Jezusie ku uczynkom dobrym, które przedtem Bóg zgotował, abyśmy w nich chodzili.",
    "ROM.10.17": "Wiara tedy jest z słuchania, a słuchanie przez słowo Boże.",
    "JAS.1.2-4": "Za największą radość miejcie, bracia moi! gdy w rozmaite pokusy wpadacie, Wiedząc, iż doświadczenie wiary waszej sprawuje cierpliwość; A cierpliwość niech ma doskonały uczynek, żebyście byli doskonali i zupełni, którym by na niczem nie schodziło.",
    "1TH.5.11": "Przetoż napominajcie jedni drugich i budujcie jeden drugiego, jako i czynicie.",
    "1PE.1.3": "Błogosławiony niech będzie Bóg i Ojciec Pana naszego, Jezusa Chrystusa, który według wielkiego miłosierdzia swego odrodził nas ku nadziei żywej przez zmartwychwstanie Jezusa Chrystusa od umarłych,",
    "JHN.1.5": "A ta światłość w ciemnościach świeci, ale ciemności jej nie ogarnęły.",
    "LEV.19.18": "Nie mścij się, i nie chowaj gniewu przeciw synom ludu twego; ale miłuj bliźniego twego, jako siebie samego; Jam Pan.",
    "MAT.5.8": "Błogosławieni czystego serca; albowiem oni Boga oglądają.",
    "ISA.61.1": "Duch Panującego Pana jest nademną; przeto mię pomazał Pan, abym opowiadał Ewangeliję cichym, posłał mię, abym związał rany tych, którzy są skruszonego serca, abym zwiastował pojmanym wyzwolenie, a więźniom otworzenie ciemnicy;",
    "RUT.1.16": "Na co jej odpowiedziała Ruta: Nie wiedź mię do tego, abym cię opuścić i od ciebie odejść miała; owszem gdziekolwiek pójdziesz, z tobą pójdę, a gdziekolwiek mieszkać będziesz, z tobą mieszkać będę; lud twój lud mój, a Bóg twój Bóg mój.",
    "JHN.8.12": "Zasię im rzekł Jezus, mówiąc: Jam jest światłość świata; kto mię naśladuje, nie będzie chodził w ciemności, ale będzie miał światłość żywota.",
    "2TH.3.3": "Aleć wierny jest Pan, który was utwierdzi i strzec będzie od złego.",
    "PSA.34.4": "Bom szukał Pana, i wysłuchał mię, a ze wszystkich strachów moich wyrwał mię.",
    "TIT.3.5": "Nie z uczynków sprawiedliwości, które byśmy my czynili, ale podług miłosierdzia swego zbawił nas przez omycie odrodzenia i odnowienia Ducha Świętego,",
    "LUK.12.32": "Nie bój się, o maluczkie stadko! albowiem się upodobało Ojcu waszemu, dać wam królestwo.",
    "PSA.23.6": "Nadto dobrodziejstwo i miłosierdzie twe pójdą za mną po wszystkie dni żywota mego, a będę mieszkał w domu Pańskim na długie czasy.",
    "MIC.7.18-19": "Któryż Bóg jest podobny tobie? Któryby nieprawość odpuszczał, i mijał przestępstwa ostatków dziedzictwa swego, któryby nie zatrzymywał na wieki gniewu swego, przeto, że się kocha w miłosierdziu. Nawróci się, a zmiłuje się nad nami; zatłumi nieprawości nasze i wrzuci w głębokość morską wszystkie grzechy nasze.",
    "2CO.4.7": "A mamy ten skarb w naczyniu glinianem, aby dostojność tej mocy była z Boga, a nie z nas.",
    "GEN.50.20": "Wyście złe myślili przeciwko mnie, ale Bóg obrócił to w dobre, chcąc uczynić to, co się dziś dzieje, aby zachował tak wielki lud.",
    "PSA.32.8": "Dam ci rozum, i nauczę cię drogi, po której masz chodzić; dam ci radę, obróciwszy na cię oko moje.",
    "MAT.6.19-21": "Nie skarbcie sobie skarbów na ziemi, gdzie mól i rdza psuje, i gdzie złodzieje podkopywują i kradną; Ale sobie skarbcie skarby w niebie, gdzie ani mól ani rdza psuje, i gdzie złodzieje nie podkopywują, ani kradną. Albowiem gdzie jest skarb wasz, tam jest i serce wasze.",
    "ROM.15.13": "A Bóg nadziei niech was napełni wszelką radością i pokojem w wierze, abyście obfitowali w nadziei przez moc Ducha Świętego.",
    "JHN.3.30": "On musi rość, a mnie musi ubywać.",
    "DEU.7.9": "A tak wiedz, że Pan, Bóg twój, jest Bóg, Bóg wierny, chowający przymierze, i miłosierdzie tym, którzy go miłują i strzegą przykazań jego, do tysięcznego pokolenia;",
    "HEB.13.8": "Jezus Chrystus wczoraj i dziś, tenże i na wieki.",
    "EPH.2.4-5": "Lecz Bóg, który jest bogaty w miłosierdziu, dla wielkiej miłości swojej, którą nas umiłował. I gdyśmy byli umarłymi w grzechach, ożywił nas pospołu z Chrystusem, (gdyż łaską zbawieni jesteście)",
    "PRO.10.12": "Nienawiść wzbudza swary; ale miłość wszystkie przestępstwa pokrywa.",
    "3JN.1.4": "Większej nad tę radości nie mam, jako gdy słyszę, iż dziatki moje chodzą w szczerości.",
    "ECC.3.1": "Każda rzecz ma swój czas, i każde przedsięwzięcie ma swój czas pod niebem.",
    "PSA.4.8": "W pokoju się i położę i zasnę, bo ty sam, Panie! czynisz, że bezpiecznie mieszkam.",
    "1CO.15.55-57": "Gdzież jest, o śmierci! bodziec twój? Gdzież jest, piekło! zwycięstwo twoje? Lecz bodziec śmierci jest grzech, a moc grzechu jest zakon. Ale niech będą Bogu dzięki, który nam dał zwycięstwo przez Pana naszego Jezusa Chrystusa.",
    "JER.29.11": "Bo Ja najlepiej wiem myśli, które myślę o was, mówi Pan: myśli o pokoju, a nie o utrapieniu, abym uczynił koniec pożądany biedom waszym.",
    "PRO.11.25": "Człowiek szczodrobliwy bywa bogatszy; a kto nasyca, sam też będzie nasycony.",
    "2PE.3.18": "Ale rośćcie w łasce i w znajomości Pana naszego i Zbawiciela, Jezusa Chrystusa, któremu niech będzie chwała i teraz, i na czasy wieczne. Amen.",
    "2TI.2.15": "Staraj się, abyś się doświadczonym stawił Bogu robotnikiem, który by się nie zawstydził i który by dobrze rozbierał słowo prawdy.",
    "PSA.107.1": "Wysławiajcie Pana: albowiem dobry; albowiem na wieki miłosierdzie jego.",
    "2CO.9.8": "A mocen jest Bóg uczynić, aby obfitowała na was wszelka łaska, abyście mając we wszystkiem zawsze wszelaki dostatek, obfitowali ku wszelakiemu uczynkowi dobremu,",
    "JHN.10.27-28": "Owce moje głosu mego słuchają, a ja je znam i idą za mną; A ja żywot wieczny daję im i nie zginą na wieki, ani ich żaden wydrze z ręki mojej.",
    "1CO.10.13": "Pokuszenie się was nie jęło, tylko ludzkie; ale wiernyć jest Bóg, który nie dopuści, abyście byli kuszeni nad możność waszę, ale uczyni z pokuszeniem i wyjście, abyście znosić mogli.",
    "MRK.11.24": "Przetoż powiadam wam: O cokolwiekbyście, modląc się, prosili, wierzcie, że weźmiecie, a stanie się wam.",
    "GAL.5.13-14": "Albowiem wy ku wolności powołani jesteście, bracia! tylko pod zasłoną tej wolności ciału nie pozwalajcie, ale z miłości służcie jedni drugim. Bo wszystek zakon w jednem się słowie zamyka, to jest w tem: Będziesz miłował bliźniego twego jako samego siebie.",
    "ACT.4.12": "I nie masz w żadnym innym zbawienia; albowiem nie masz żadnego imienia pod niebem, danego ludziom, przez które byśmy mogli być zbawieni.",
    "ISA.41.10": "Nie bój się! bom Ja z tobą. Nie lękaj się! bom Ja Bogiem twoim. Zmocnię cię, a dam ci pomoc, i podeprę cię prawicą sprawiedliwości swojej.",
    "1JN.4.16": "I myśmy poznali i uwierzyli o miłości, którą Bóg ma ku nam. Bóg jest miłość; a kto mieszka w miłości, w Bogu mieszka, a Bóg w nim.",
    "EXO.15.2": "Moc moja i chwała moja Pan, bo mi się stał zbawieniem; ten jest Bogiem moim, przetoż przybytek wystawię mu; Bóg ojca mego, przetoż wywyższać go będę.",
    "REV.22.13": "Jam jest Alfa i Omega, początek i koniec, pierwszy i ostateczny.",
    "2TI.4.7-8": "Dobrym bój bojował, biegem wykonał, wiaręm zachował; Zatem odłożona mi jest korona sprawiedliwości, którą mi odda w on dzień Pan, sędzia sprawiedliwy, a nie tylko mnie, ale i wszystkim, którzy umiłowali sławne przyjście jego.",
    "PSA.121.7-8": "Pan cię strzec będzie od wszystkiego złego; on duszy twojej strzec będzie. Pan strzec będzie wyjścia twego i wejścia twego, odtąd aż na wieki.",
    "ISA.53.5": "Lecz on zraniony jest dla występków naszych, starty jest dla nieprawości naszych; kaźń pokoju naszego jest na nim, a sinością jego jesteśmy uzdrowieni.",
    "ROM.10.9-10": "Że jeźlibyś usty wyznał Pana Jezusa i uwierzyłbyś w sercu twojem, że go Bóg z martwych wzbudził, zbawiony będziesz. Albowiem sercem wierzono bywa ku sprawiedliwości, ale się usty wyznanie dzieje ku zbawieniu.",
    "1PE.2.24": "Który grzechy nasze na ciele swoim zaniósł na drzewo, abyśmy obumarłszy grzechom sprawiedliwości żyli, którego sinością uzdrowieni jesteście.",
    "2PE.1.3": "Jako nam jego Boska moc wszystko, co do żywota i do pobożności należy, darowała przez poznanie tego, który nas powołał przez sławę i przez cnotę;",
    "PSA.94.19": "W wielkości utrapienia mego, we wnętrznościach moich, pociechy twoje rozweselały duszę moję.",
    "MAT.6.34": "Przetoż nie troszczcie się o jutrzejszy dzień: albowiem jutrzejszy dzień troskać się będzie o swoje potrzeby. Dosyćci ma dzień na swojem utrapieniu.",
    "PHP.4.4": "Radujcie się zawsze w Panu; znowu mówię, radujcie się.",
    "EPH.2.8-9": "Albowiem łaską jesteście zbawieni przez wiarę, i to nie jest z was, dar to Boży jest; Nie z uczynków, aby się kto nie chlubił.",
    "1PE.5.10": "A Bóg wszelkiej łaski, który nas powołał do wiecznej chwały swojej w Chrystusie Jezusie, gdy maluczko ucierpicie, ten niech was doskonałymi uczyni, utwierdzi, umocni i ugruntuje;",
    "ACT.1.8": "Ale przyjmiecie moc Ducha Świętego, który przyjdzie na was; i będziecie mi świadkami i w Jeruzalemie, i we wszystkiej Judzkiej ziemi, i w Samaryi, aż do ostatniego kraju ziemi.",
    "JHN.3.16": "Albowiem tak Bóg umiłował świat, że Syna swego jednorodzonego dał, aby każdy, kto weń wierzy, nie zginął, ale miał żywot wieczny.",
    "1CH.16.11": "Szukajcie Pana, i mocy jego; szukajcie oblicza jego zawżdy.",
    "1TI.4.12": "Żaden młodością twoją niech nie gardzi; ale bądź przykładem wiernych w mowie, w obcowaniu, w miłości, w duchu, w wierze, w czystości.",
    "EPH.6.10-11": "Na ostatek, bracia moi! zmacniajcie się w Panu i w sile mocy jego; Obleczcie się w zupełną zbroję Bożą, abyście mogli stać przeciwko zasadzkom dyjabelskim.",
    "JHN.15.12-13": "Toć jest przykazanie moje, abyście się społecznie miłowali, jakom i ja was umiłował. Większej miłości nad tę żaden nie ma, jedno gdyby kto duszę swoję położył za przyjacioły swoje.",
    "ZEC.4.6": "Tedy odpowiadając rzekł do mnie, mówiąc: Toć jest słowo Pańskie do Zorobabela mówiące: Nie wojskiem ani siłą stanie się to, ale duchem moim, mówi Pan zastępów.",
    "ROM.8.37": "Ale w tem wszystkiem przezwyciężamy przez tego, który nas umiłował.",
    "PRO.1.7": "Bojaźń Pańska jest początkiem umiejętności; ale głupi mądrością i ćwiczeniem gardzą.",
    "PSA.27.14": "Oczekujże Pana, zmacniaj się, a on utwierdzi serce twoje; przetoż oczekuj Pana.",
    "MRK.16.15": "I rzekł im: Idąc na wszystek świat, każcie Ewangieliję wszystkiemu stworzeniu.",
    "JHN.16.33": "Tomci wam powiedział, abyście we mnie pokój mieli. Na świecie ucisk mieć będziecie; ale ufajcie, jam zwyciężył świat.",
    "1PE.4.8": "Przetoż trzeźwymi bądźcie i czułymi ku modlitwom, a nade wszystko miejcie uprzejmą miłość jedni ku drugim; albowiem miłość zakryje mnóstwo grzechów.",
    "PRO.3.5-6": "Ufaj w Panu ze wszystkiego serca twego, a na rozumie twoim nie spolegaj. We wszystkich drogach twoich znaj go, a on prostować będzie ścieszki twoje.",
    "ROM.8.31-32": "Cóż tedy rzeczemy na to? Jeźli Bóg za nami, któż przeciwko nam? Który ani własnemu Synowi nie przepuścił, ale go za nas wszystkich wydał: jakoż by wszystkiego z nim nie darował nam?",
    "HAB.3.19": "Panujący Pan jest siłą moją, który czyni nogi moje, jako nogi łani, i po miejscach wysokich poprowadzi mię. Przedniejszemu nad śpiewakami na muzycznem naczyniu mojem.",
    "MIC.6.8": "Oznajmił ci człowiecze, co jest dobrego, i czegoż Pan chce po tobie; tylko abyś czynił sąd, a miłował miłosierdzie i pokornie chodził z Bogiem twoim.",
    "MAT.17.20": "Lecz Jezus rzekł do nich: Dla niedowiarstwa waszego; zaprawdę bowiem powiadam wam: Jeźlibyście, mając wiarę jako ziarno gorczyczne, rzekli tej górze: Przenieś się stąd na ono miejsce, tedy się przeniesie, a nic niemożebnego wam nie będzie.",
    "MRK.10.45": "Bo i Syn człowieczy nie przyszedł, aby mu służono, ale aby służył, i aby dał duszę swą na okup za wielu.",
    "DAN.12.3": "Ale ci, którzy innych nauczają, świecić się będą jako światłość na niebie, a którzy wielu ku sprawiedliwości przywodzą, jako gwiazdy na wieki wieczne.",
    "PHP.4.6-7": "Nie troszczcie się o żadną rzecz, ale we wszystkiem przez modlitwę i prośbę z dziękowaniem żądności wasze niech będą znajome u Boga. A pokój Boży, który przewyższa wszelki rozum, będzie strzegł serc waszych i myśli waszych w Chrystusie Jezusie.",
    "2CO.4.8-9": "Gdy zewsząd uciśnieni bywamy, ale nie bywamy potłoczeni; powątpiewamy, ale nie zwątpimy. Prześladowanie cierpimy, ale nie bywamy opuszczeni; bywamy porzuceni, ale nie giniemy.",
    "PRO.16.24": "Powieści wdzięczne są jako plastr miodu, słodkością duszy, a lekarstwem kościom.",
    "1JN.1.5": "A toć jest poselstwo, któreśmy słyszeli od niego i zwiastujemy wam: Iż Bóg jest światłość, a żadnej ciemności w nim nie masz.",
    "DEU.6.4-5": "Słuchajże Izraelu: Pan, Bóg nasz, Pan jeden jest. Będziesz tedy miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, i ze wszystkiej siły twojej;",
    "PSA.23.4": "Choćbym też chodził w dolinie cienia śmierci, nie będę się bał złego, albowiemeś ty ze mną; laska twoja, i kij twój, te mię cieszą.",
    "ROM.8.18": "Albowiem, (bracia!) mam za to, iż utrapienia teraźniejszego czasu nie są godne onej przyszłej chwały, która się ma objawić w nas.",
    "REV.3.20": "Oto stoję u drzwi i kołaczę; jeźliby kto usłyszał głos mój i otworzył drzwi, wnijdę do niego i będę z nim wieczerzał, a on ze mną.",
    "ISA.30.15": "Albowiem tak mówi panujący Pan, Święty, Izraelski: Jeźli się nawrócicie i uspokoicie się, zachowani będziecie; w milczeniu i w nadziei będzie moc wasza. Ale nie chcecie;",
    "JHN.6.35": "I rzekł im Jezus: Jamci jest on chleb żywota; kto do mnie przychodzi, łaknąć nie będzie, a kto wierzy w mię, nigdy pragnąć nie będzie.",
    "ACT.20.35": "Wszystkomci wam okazał, iż tak pracując, musimy podejmować słabe, a pamiętać na słowa Pana Jezusowe, że on rzekł: Szczęśliwsza jest rzecz dawać, niżeli brać.",
    "JAS.5.16": "Wyznawajcie jedni przed drugimi upadki, a módlcie się za drugimi; abyście byli uzdrowieni. Wiele może uprzejma modlitwa sprawiedliwego.",
    "ISA.1.18": "Przyjdźcież teraz, a rozpierajmy się z sobą, mówi Pan: Choćby były grzechy wasze jako szarłat, jako śnieg zbieleją; choćby były czerwone jako karmazyn, jako wełna białe będą.",
    "PRO.27.17": "Żelazo żelazem bywa naostrzone; tak mąż zaostrza oblicze przyjaciela swego.",
    "JHN.1.14": "A to Słowo ciałem się stało, i mieszkało między nami, i widzieliśmy chwałę jego, chwałę jako jednorodzonego od Ojca, pełne łaski i prawdy.",
    "1JN.1.9": "Jeźlibyśmy wyznali grzechy nasze, wiernyć jest Bóg i sprawiedliwy, aby nam odpuścił grzechy i oczyścił nas od wszelkiej nieprawości.",
    "MAT.6.33": "Ale szukajcie naprzód królestwa Bożego, i sprawiedliwości jego, a to wszystko będzie wam przydano.",
    "1CO.13.12": "Albowiem teraz widzimy przez zwierciadło i niby w zagadce; ale na on czas twarzą w twarz; teraz poznaję po części, ale na on czas poznam, jakom i poznany jest.",
    "REV.1.8": "Jam jest Alfa i Omega, początek i koniec, mówi Pan, który jest i który był, i który przyjść ma, on Wszechmogący.",
    "PSA.28.7": "Pan jest mocą moją i tarczą moją, w nim, nadzieję ma serce moje, a jestem poratowany; przetoż się rozweseliło serce moje, a pieśnią moją chwalić go będę.",
    "DEU.31.8": "A Pan on pójdzie przed tobą, on będzie z tobą, nie odstąpi cię, ani cię opuści; nie bójże się, ani się lękaj.",
    "HEB.4.12": "Boć żywe jest słowo Boże i skuteczne, i przeraźliwsze nad wszelki miecz po obu stronach ostry, i przenikające aż do rozdzielenia i duszy, i ducha, i stawów, i szpików, i rozeznawające myśli i zdania serdeczne.",
    "MAT.19.14": "Lecz Jezus rzekł: Zaniechajcie dziatek, a nie zabraniajcie im przychodzić do mnie; albowiem takich jest królestwo niebieskie.",
    "JAS.4.7-8": "Poddajcież się tedy Bogu, a dajcie odpór dyjabłu, a uciecze od was. Przybliżcie się ku Bogu, a przybliży się ku wam. Ochędóżcie ręce grzesznicy i oczyście serca, którzyście umysłu dwoistego,",
    "PSA.139.13-14": "Ty zaiste w nocy masz nerki moje; okryłeś mię w żywocie matki mojej. Wysławiam cię dlatego, że się zdumiewam strasznym i dziwnym sprawom twoim, a dusza moja zna je wybornie.",
    "HOS.6.3": "Tedy poznawszy Pana starać się będziemy, abyśmy go więcej poznali; bo wyjście jego jako ranna zorza zgotowane jest, a przyjdzie nam jako deszcz na wiosnę i w jesieni na zimę.",
    "1CO.10.31": "Przetoż lub jecie lub pijecie, lub cokolwiek czynicie, wszystko ku chwale Bożej czyńcie.",
    "JOS.1.8": "Niech nie odstępują księgi zakonu tego od ust twoich; ale rozmyślaj w nich we dnie i w nocy, abyś strzegł i czynił wszystko, co napisano w nim; albowiem na ten czas poszczęścią się drogi twoje, i na ten czas roztropnym będziesz.",
    "2CH.7.14": "A jeźliby się upokorzył lud mój, nad którym wzywano imienia mego, a modliłby się, i szukałby twarzy mojej, odwróciwszy się od dróg swoich złych: tedy Ja wysłucham z nieba, i odpuszczę grzech ich, a uzdrowię ziemię ich.",
    "PSA.19.14": "Niechże będą przyjemne słowa ust moich, i rozmyślanie serca mego przed obliczem twojem, Panie, skało moja, i odkupicielu mój!",
    "JHN.14.1-3": "Niechaj się nie trwoży serce wasze; wierzycie w Boga i w mię wierzycie. W domu Ojca mego wiele jest mieszkania; a jeźli nie, wżdybymci wam powiedział. Idę, abym wam zgotował miejsce; a gdy odejdę i zgotuję wam miejsce, przyjdę zasię i wezmę was do siebie, żebyście, gdziem ja jest, i wy byli.",
    "PSA.147.3": "Który uzdrawia skruszonych na sercu, a zawiązuje boleści ich.",
    "PHP.4.19": "A Bóg mój napełni wszelką potrzebę waszę według bogactwa swego, chwalebnie, w Chrystusie Jezusie.",
    "2CO.13.14": "Łaska Pana Jezusa Chrystusa i miłość Boża, i społeczność Ducha Świętego niech będzie z wami wszystkimi. Amen.",
    "1PE.3.15": "Bądźcie zawsze gotowi ku daniu odpowiedzi każdemu domagającemu się od was rachunku o tej nadziei, która w was jest, z cichością i z bojaźnią, mając sumienie dobre;",
    "MAT.25.40": "A odpowiadając król, rzecze im: Zaprawdę powiadam wam, cokolwiekieście uczynili jednemu z tych braci moich najmniejszych, mnieście uczynili.",
    "PSA.139.23-24": "Wyszpieguj mię, Boże! a poznaj serce moje; doświadcz mię, a poznaj myśli moje, I obacz, jeźli droga odporności jest we mnie, a prowadź mię drogą wieczną.",
    "JOS.1.9": "Azażemci nie rozkazał: Zmocnij się, i mężnie sobie poczynaj, nie lękaj się, a nie trwóż sobą, albowiem z tobą jest Pan, Bóg twój, we wszystkiem, do czegokolwiek się obrócisz?",
    "JAS.3.17-18": "Ale mądrość, która jest z góry, najprzódci jest czysta, potem spokojna, mierna, powolna, pełna miłosierdzia i owoców dobrych, nieposądzająca, i nieobłudna. Ale owoc sprawiedliwości w pokoju bywa siany tym, którzy pokój czynią.",
    "REV.22.17": "A Duch i oblubienica mówią: Przyjdź! A kto słyszy, niech rzecze: Przyjdź! A kto pragnie, niech przyjdzie; a kto chce, niech bierze wodę żywota darmo.",
    "MAT.19.26": "A Jezus wejrzawszy na nie, rzekł im: U ludzić to nie można; lecz u Boga wszystko jest możebne.",
    "PSA.103.11-12": "Albowiem jako są niebiosa wysokie nad ziemią, tak jest utwierdzone miłosierdzie jego nad tymi, którzy się go boją; A jako daleko jest wschód od zachodu, tak daleko oddalił od nas przestępstwa nasze.",
    "REV.4.11": "Godzieneś jest, Panie! wziąć chwałę i cześć, i moc; boś ty stworzył wszystkie rzeczy i za wolą twoją trwają, i stworzone są.",
    "PHP.1.21": "Albowiem mnie życiem jest Chrystus, a umrzeć zysk.",
    "2TI.3.16-17": "Wszystko Pismo od Boga jest natchnione i pożyteczne ku nauce, ku strofowaniu, ku naprawie, ku ćwiczeniu, które jest w sprawiedliwości; Aby człowiek Boży był doskonały, ku wszelkiej sprawie dobrej dostatecznie wyćwiczony.",
    "JER.31.3": "Rzeczeszli: Zdawna mi się Pan ukazywał. I owszem, miłością wieczną umiłowałem cię, dlategoć ustawicznie miłosierdzie pokazuję;",
    "LUK.15.7": "Powiadam wam, że taka będzie radość w niebie nad jednym grzesznikiem pokutującym, więcej niż nad dziewięćdziesiąt i dziewięciu sprawiedliwych, którzy nie potrzebują pokuty.",
    "ISA.54.10": "A choćby się i góry poruszyły, i pagórki się zachwiały: jednak miłosierdzie moje od ciebie nie odstąpi, a przymierze pokoju mego nie wzruszy się, mówi twój miłościwy Pan.",
    "EPH.3.20-21": "A temu, który może nade wszystko uczynić daleko obficiej niżeli prosimy albo myślimy, według onej mocy, która skuteczna jest w nas; Temu niech będzie chwała w kościele przez Chrystusa Jezusa po wszystkie czasy na wieki wieków. Amen.",
    "ROM.5.3-5": "A nie tylko to, ale się też chlubimy z ucisków, wiedząc, iż ucisk cierpliwość sprawuje, A cierpliwość doświadczenie, a doświadczenie nadzieję, A nadzieja nie pohańbia, przeto iż miłość Boża rozlana jest w sercach naszych przez Ducha Świętego, który nam jest dany.",
    "1JN.4.19": "My go miłujemy, iż on nas pierwej umiłował.",
    "JHN.14.6": "Rzekł mu Jezus: Jamci jest ta droga, i prawda, i żywot; żaden nie przychodzi do Ojca, tylko przez mię.",
    "1PE.5.6-7": "Uniżajcież się tedy pod mocną ręką Bożą, aby was wywyższył czasu swego; Wszystko staranie wasze wrzuciwszy na niego, gdyż on ma pieczę o was.",
    "EST.4.14": "Albowiem, jeźli ty tak cale milczeć będziesz na ten czas, ulżenie i wybawienie przyjdzie Żydom skąd inąd, ale ty i dom ojca twego zginiecie; a któż wie, jeźliś nie dla tego czasu dostąpiła królestwa?",
    "PSA.51.10": "Serce czyste stwórz we mnie, o Boże! a ducha prawego odnów we wnętrznościach moich.",
    "LUK.6.37-38": "Nie sądźcie, a nie bądziecie sądzeni; nie potępiajcie, a nie będziecie potępieni, a będzie wam odpuszczono. Dawajcie, a będzie wam dano; miarę dobrą, natłoczoną, i potrzęsioną, i opływającą dadzą na łono wasze; albowiem tąż miarą, którą mierzycie, będzie wam zaś obmierzono.",
    "PRO.2.6": "Albowiem Pan daje mądrość, z ust jego pochodzi umiejętność i roztropność.",
    "MAT.7.24-25": "Wszelkiego tedy, który słucha tych słów moich i czyni je, przypodobam mężowi mądremu, który zbudował dom swój na opoce; I spadł gwałtowny deszcz, i przyszła powódź, i wiatry wiały, i uderzyły na on dom, ale nie upadł, bo był założony na opoce.",
    "TIT.2.11-13": "Albowiem okazała się łaska Boża, zbawienna wszystkim ludziom, Ćwicząca nas, abyśmy odrzekłszy się niepobożności i świeckich pożądliwości, trzeźwie i sprawiedliwie, i pobożnie żyli na tym świecie, Oczekując onej błogosławionej nadziei i objawienia chwały wielkiego Boga i zbawiciela naszego, Jezusa Chrystusa;",
    "LUK.2.14": "Chwała na wysokościach Bogu, a na ziemi pokój, w ludziach dobre upodobanie.",
    "JOB.23.10": "Gdyż on zna drogę moję; a będzieli mię doświadczał, jako złoto wynijdę.",
    "2CO.9.6-7": "Ale tak mówię: Kto skąpo sieje, skąpo też żąć będzie; a kto obficie sieje, obficie też żąć będzie. Każdy jako umyślił w sercu swem, tak niech uczyni, nie z zamarszczeniem ani z przymuszenia; albowiem ochotnego dawcę Bóg miłuje.",
    "PRO.19.21": "Wiele jest myśli w sercu człowieczem; ale rada Pańska, ta się ostoi.",
    "ROM.5.1-2": "Będąc tedy usprawiedliwieni z wiary, pokój mamy z Bogiem przez Pana naszego Jezusa Chrystusa; Przez któregośmy też przystęp otrzymali wiarą ku łasce, w której stoimy i chlubimy się nadzieją chwały Bożej.",
    "LUK.6.27-28": "Ale wam powiadam, którzy słuchacie: Miłujcie nieprzyjacioły wasze, czyńcie dobrze tym, którzy was mają w nienawiści. Błogosławcie tym, którzy was przeklinają; módlcie się za tymi, którzy wam złość wyrządzają.",
    "PRO.22.6": "Ćwicz młodego według potrzeby drogi jego; bo gdy się zstarzeje, nie odstąpi od niej.",
    "NUM.23.19": "Nie jestci Bóg jako człowiek, aby kłamał, ani jako syn człowieczy, ażeby żałował; azaż on rzecze, a nie uczyni? wymówi, a nie wypełni?",
    "PHP.4.8": "A dalej mówiąc, bracia, cokolwiek jest prawdziwego, cokolwiek poczciwego, cokolwiek sprawiedliwego, cokolwiek czystego, cokolwiek przyjemnego, cokolwiek chwalebnego, jeźli która cnota i jeźli która chwała, o tem przemyślajcie.",
    "COL.2.6-7": "Przetoż jakoście przyjęli Pana Jezusa Chrystusa, tak w nim chodźcie, Będąc wkorzenieni i wybudowani na nim, i utwierdzeni w wierze, jakoście się nauczyli, obfitując w niej z dziękowaniem.",
    "ROM.12.12": "W nadziei się weselący, w ucisku cierpliwi, w modlitwie ustawiczni;",
    "PHP.2.3-4": "Nic nie czyniąc spornie, albo przez próżną chwałę, ale w pokorze jedni drugich mając za wyższych nad się. Nie upatrujcie każdy tylko, co jest jego, ale każdy też, co jest drugich.",
    "1JN.5.14-15": "A toć jest ufanie, które mamy do niego, iż jeźlibyśmy o co prosili według woli jego, słyszy nas. A jeźli wiemy, iż nas słyszy, o cokolwiek byśmy prosili, tedy wiemy, iż mamy te rzeczy, o któreśmy go prosili.",
    "EPH.5.8": "Albowiemeście byli niekiedy ciemnością; aleście teraz światłością w Panu; chodźcież jako dziatki światłości,",
    "1JN.4.7-8": "Najmilsi! miłujmyż jedni drugich, gdyż miłość jest z Boga; i każdy, co miłuje, z Boga jest narodzony i zna Boga. Kto nie miłuje, nie zna Boga; gdyż Bóg jest miłość.",
    "PSA.103.1-2": "Błogosław duszo moja Panu, i wszystkie wnętrzności moje imieniowi jego świętemu. Błogosławże duszo moja Panu, a nie zapominaj wszystkich dobrodziejstw jego.",
    "HOS.6.6": "Bo miłosierdzia chcę, a nie ofiary, a znajomości Bożej więcej, niż całopalenia.",
    "ROM.8.1": "Przetoż teraz żadnego potępienia nie masz tym, który będąc w Chrystusie Jezusie nie według ciała chodzą, ale według Ducha.",
    "ISA.60.1": "Powstań, objaśnij się! ponieważ przyszła światłość twoja, a chwała Pańska weszła nad tobą.",
    "1TH.5.23-24": "A sam Bóg pokoju niech was zupełnie poświęci; a cały duch wasz, i dusza, i ciało niech będą bez nagany na przyjście Pana naszego, Jezusa Chrystusa, zachowane. Wiernyż jest ten, który was powołał, który też to uczyni,",
    "1CO.6.19-20": "Azaż nie wiecie, iż ciało wasze jest kościołem Ducha Świętego, który w was jest, którego macie od Boga? a nie jesteście sami swoi; Albowiemeście drogo kupieni. Wysławiajcież tedy Boga w ciele waszym i w duchu waszym, które są Boże.",
    "GEN.28.15": "A oto, Ja jestem z tobą i strzec cię będę gdziekolwiek pójdziesz, i przywrócę cię do tej ziemi; bo nie opuszczę cię, aż uczynię com ci rzekł.",
    "PSA.73.26": "Choć ciało moje, i serce moje ustanie, jednak Bóg jest skałą serca mego, i działem moim na wieki.",
    "SNG.8.7": "Wody wielkie nie mogłyby zagasić tej miłości, ani rzeki zatopić; choćby kto wszystkę majętność domu swego dał za takową miłość, byłby pewnie wzgardzony.",
    "JER.32.17": "Ach panujący Panie!otoś ty uczynił niebo i ziemię mocą swoją wielką i ramianiem twoim wyciągnionem, nie jestci skryta przed tobą żadna rzecz;",
    "1CH.16.34": "Wysłwiajcie Pana; albowiem dobry, bo na wieki trwa miłosierdzie jego.",
    "GAL.5.1": "Stójcie tedy w tej wolności, którą nas Chrystus wolnymi uczynił, a nie poddawajcie się znowu pod jarzmo niewoli.",
    "PSA.34.18": "Bliski jest Pan tym, którzy są skruszonego serca, a utrapionych w duchu zachowuje.",
    "DAN.3.17-18": "Bo oto lubo Bóg nasz, którego my chwalimy, (który mocen jest wyrwać nas z pieca ogniem pałającego, i z ręki twojej, o królu!) wyrwie nas, Lubo nie wyrwie, niech ci będzie wiadomo, o królu! że bogów twoich chwalić, i obrazowi złotemu, któryś wystawił, kłaniać się nie będziemy.",
    "1TI.1.17": "Przetoż królowi wieków nieśmiertelnemu, niewidzialnemu samemu mądremu Bogu, niech będzie cześć i chwała na wieki wieków. Amen.",
    "PSA.86.5": "Boś ty, Panie! dobry i litościwy, i wielce miłosierny wszystkim, którzy cię wzywają.",
    "AMO.5.24": "Ale sąd nawalnie popłynie, jako woda, a sprawiedliwość jako strumień gwałtowny.",
    "JAS.1.17": "Wszelki datek dobry i wszelki dar doskonały z góry jest, zstępujący od Ojca światłości, u którego nie masz odmiany, ani zaćmienia na wstecz się wracającego.",
    "JUD.1.24-25": "A temu, który was może zachować od upadku i stawić przed oblicznością chwały swojej bez nagany z weselem, Samemu mądremu Bogu, Zbawicielowi naszemu, niech będzie chwała i wielmożność, moc i zwierzchność, i teraz i po wszystkie wieki. Amen.",
    "2PE.3.9": "Nie omieszkiwać Pan z obietnicą, (jako to niektórzy mają za omieszkanie), ale używa cierpliwości przeciwko nam, nie chcąc, aby którzy zginęli, ale żeby się wszyscy do pokuty udali.",
    "ISA.9.6": "Albowiem dziecię narodziło się nam, a syn dany jest nam; i będzie panowanie na ramieniu jego, a nazwią imię jego: Dziwny, Radny, Bóg mocny, Ojciec wieczności, Książę pokoju;",
    "LUK.2.10-11": "I rzekł do nich Anioł: Nie bójcie się; bo oto zwiastuję wam radość wielką, która będzie wszystkiemu ludowi: Iż się wam dziś narodził zbawiciel, który jest Chrystus Pan, w mieście Dawidowem.",
    "1TI.6.6-8": "A jestci wielki zysk pobożność z przestawaniem na swem; Albowiem niceśmy nie przynieśli na ten świat, bez pochyby że też wynieść nic nie możemy; Ale mając żywność i odzienie, na tem przestawać mamy.",
    "NAM.1.7": "Dobry jest Pan, i posila w dzień uciśnienia, a zna tych, którzy ufają w nim;",
    "PSA.27.1": "Pan jest światłością moją, i zbawieniem mojem, kogóż się bać będę? Pan jest mocą żywota mego, kogóż się mam lękać?",
    "COL.1.15-17": "Który jest obrazem Boga niewidzialnego i pierworodny wszystkich rzeczy stworzonych. Albowiem przezeń stworzone są wszystkie rzeczy, które są na niebie i na ziemi, widzialne i niewidzialne, bądź trony, bądź państwa, bądź księstwa, bądź zwierzchności, wszystko przezeń i dla niego stworzone jest. A on jest przed wszystkimi i wszystko w nim stoi.",
    "ZEP.3.17": "Pan, Bóg twój, w pośrodku ciebie mocny zachowa cię, rozweseli się wielce nad tobą, przestanie na miłości swej przeciwko tobie, i rozweseli się nad tobą z śpiewaniem, mówiąc:",
    "PSA.90.12": "Nauczże nas obliczać dni naszych, abyśmy przywiedli serce do mądrości.",
    "ROM.8.24-25": "Albowiem nadziejąśmy zbawieni. A nadzieja widoma nie jest nadzieją; bo co kto widzi, przecz się tego spodziewa? Ale czego nie widzimy, tego się spodziewamy i tego przez cierpliwość oczekujemy.",
    "PSA.39.7": "A teraz na cóż oczekuję, Panie? Tyś jest sam oczekiwaniem mojem.",
    "LAM.3.21-23": "Przywodząc to sobie do serca swego, mam nadzieję. Wielkie jest miłosierdzie Pańskie, żeśmy do szczętu nie zginęli; nie ustawają zaiste litości jego. Ale się na każdy poranek odnawiają; wielka jest prawda twoja.",
    "PSA.71.5": "Albowiemeś ty oczekiwaniem mojem, Panie! Panie! nadziejo moja od młodości mojej.",
    "HEB.6.19": "Którą mamy jako kotwicę duszy, i bezpieczną, i pewną, i wchodzącą aż wewnątrz za zasłonę,",
    "PSA.130.5": "Oczekuję na Pana; oczekuje dusza moja, i jeszcze oczekuje na słowo jego.",
    "PRO.23.18": "Bo iż jest zapłata, przeto nadzieja twoja nie będzie wykorzeniona.",
    "PSA.42.11": "Przeczże się smucisz, duszo moja? a przecz sobą trwożysz we mnie? Czekaj na Boga; albowiem go jeszcze będę wysławiał, gdyż on jest wielkiem zbawieniem twarzy mojej, i Bogiem moim.",
    "TIT.2.13": "Oczekując onej błogosławionej nadziei i objawienia chwały wielkiego Boga i zbawiciela naszego, Jezusa Chrystusa;",
    "HEB.10.23": "I omyte ciało wodą czystą, trzymajmy wyznanie nadziei niechwiejące się; (boć wierny jest ten, który obiecał;)",
    "PSA.33.22": "Niechże będzie miłosierdzie twoje, Panie! nad nami, jakośmy nadzieję w tobie mieli.",
    "1PE.1.13": "Przetoż przepasawszy biodra myśli waszej i trzeźwymi będąc, doskonałą miejcie nadzieję ku tej łasce, która wam dana będzie w objawienie Jezusa Chrystusa,",
    "PSA.31.24": "Zmacniajcie się (a posili Bóg serca wasze) wszyscy, którzy nadzieję macie w Panu.",
    "COL.1.27": "Którym chciał Bóg oznajmić, jakie jest bogactwo tej tajemnicy chwalebnej między poganami, która jest Chrystus między wami, nadzieja ona chwały;",
    "PSA.62.5": "Ty przecież na Bogu spolegaj, duszo moja! bo od niego jest oczekiwanie moje.",
    "PSA.147.11": "Kocha się Pan w tych, którzy się go boją, a którzy ufają w miłosierdziu jego.",
    "1TH.4.13-14": "A nie chcę, bracia! abyście wiedzieć nie mieli o tych, którzy zasnęli, iżbyście się nie smucili, jako i drudzy, którzy nadziei nie mają. Albowiem jeźli wierzymy, iż Jezus umarł i zmartwychwstał, tak Bóg i tych, którzy zasnęli w Jezusie, przywiedzie z nim.",
    "PRO.13.12": "Nadzieja długa wątli serce; ale żądość wypełniona jest drzewem żywota.",
    "PSA.119.114": "Tyś jest ucieczką moją, i tarczą moją; na słowo twoje oczekuję.",
    "2CO.4.17-18": "Albowiem ten króciuchny i lekki ucisk nasz nader zacnej chwały wieczną wagę nam sprawuje; Gdy nie patrzymy na rzeczy widzialne, ale na niewidzialne; albowiem rzeczy widzialne są doczesne, ale niewidzialne są wieczne.",
    "ISA.26.3-4": "Człowieka spolegającego na tobie zachowywasz w pokoju, w pokoju mówię: bo w tobie ufa. Miejcie nadzieję w Panu aż na wieki; boć w Panu, w Panu jest skała wieczna.",
    "PSA.37.5": "Spuść na Pana drogę twoję, a ufaj w nim, a on wszystko uczyni;",
    "PSA.9.10": "I będą ufać w tobie, którzy znają imię twoje; albowiem nie opuszczasz tych, Panie! którzy cię szukają.",
    "PSA.20.7": "Jedni w wozach, a drudzy w koniach ufają; ale my na imię Pana, Boga naszego, wspominamy.",
    "PSA.62.8": "Ufajcież w nim na każdy czas, o narody! Wylewajcie przed obliczem jego serca wasze: Bóg jest ucieczką naszą. Sela.",
    "PSA.112.7": "Słysząc złe nowiny, nie boi się; stateczne serce jego ufa w Panu.",
    "PSA.118.8": "Lepiej mieć nadzieję w Panu, niżeli ufać w człowieku.",
    "ISA.12.2": "Oto Bóg zbawienie moje, ufać będę, a nie ulęknę się; albowiem Pan, Bóg mój, jest mocą moją, i pieśnią moją, i zbawieniem mojem.",
    "PSA.125.1": "Którzy ufają w Panu, są jako góra Syon, która się nie poruszy, ale na wieki zostaje.",
    "PSA.143.8": "Spraw, abym rano słyszał miłosierdzie twoje, bo w tobie ufam; oznajmij mi drogę, którąbym miał chodzić; bo do ciebie podnoszę duszę moję.",
    "PRO.29.25": "Strach człowieczy stawia sobie sidło; ale kto ma nadzieję w Panu, wywyższony będzie.",
    "PSA.91.2": "Rzecze Panu: Nadzieja moja i zamek mój, Bóg mój, w nim nadzieję mieć będę.",
    "2CO.5.7": "(Bo przez wiarę chodzimy, a nie przez widzenie).",
    "PSA.40.4": "Błogosławiony człowiek, który pokłada w Panu nadzieję swoję, a nie ogląda się na hardych, ani na tych, którzy się unoszą za kłamstwem.",
    "PSA.13.5-6": "Ale ja w miłosierdziu twojem ufam: rozraduje się serce moje w zbawieniu twojem; będę śpiewał Panu, że mi dał wiele dobrego.",
    "PSA.84.12": "Panie zastępów! błogosławiony człowiek, który ma nadzieję w tobie.",
    "PRO.16.20": "Kto ma wzgląd na słowa, znajduje dobre; a kto ufa w Panu, błogosławiony jest.",
    "PSA.32.10": "Wiele boleści przypada na złośnika; ale ufającego w Panu miłosierdzie ogarnie.",
    "ISA.50.10": "Kto jest między wami bojący się Pana, posłuchaj głosu sługi jego; kto jest, co chodzi w ciemnościach a nie ma światłości? ufaj w imieniu Pańskiem, a spolegaj na Bogu swoim.",
    "PSA.37.3": "Ufaj w Panu, a czyń dobrze; mieszkajże na ziemi, a żyw się sprawiedliwie.",
    "PSA.115.11": "Którzy się boicie Pana, ufajcie w Panu; on jest pomocnikiem i tarczą ich.",
    "ROM.4.20-21": "O obietnicy tedy Bożej nie wątpił z niedowiarstwa; ale się umocnił wiarą i dał chwałę Bogu, Będąc też tego pewien, że cokolwiek on obiecał, mocen jest i uczynić.",
    "1JN.4.18-19": "Nie maszci bojaźni w miłości, ale miłość doskonała precz wyrzuca bojaźń: bo bojaźń ma udręczenie, a kto się boi, nie jest doskonały w miłości. My go miłujemy, iż on nas pierwej umiłował.",
    "1JN.3.18": "Dziateczki moje! nie miłujmy słowem ani językiem, ale uczynkiem i prawdą.",
    "COL.3.14": "A nad to wszystko (przyobleczcie) miłość, która jest związką doskonałości.",
    "ROM.13.10": "Miłość bliźniemu złości nie wyrządza; a tak wypełnieniem zakonu jest miłość.",
    "DEU.6.5": "Będziesz tedy miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, i ze wszystkiej siły twojej;",
    "1CO.16.14": "Wszystkie rzeczy wasze niech się dzieją w miłości.",
    "EPH.5.2": "A chodźcie w miłości, jako i Chrystus umiłował nas i wydał samego siebie na ofiarę i na zabicie Bogu ku wdzięcznej wonności.",
    "GAL.5.13": "Albowiem wy ku wolności powołani jesteście, bracia! tylko pod zasłoną tej wolności ciału nie pozwalajcie, ale z miłości służcie jedni drugim.",
    "PSA.136.26": "Wysławiajcież Boga niebios; albowiem na wieki miłosierdzie jego.",
    "LUK.6.35": "Owszem miłujcie nieprzyjacioły wasze, i czyńcie im dobrze, i pożyczajcie, nic się stąd nie spodziewając, a będzie wielka zapłata wasza, i będziecie synami Najwyższego; albowiem on dobrotliwy jest przeciw niewdzięcznym i złym.",
    "ROM.12.9-10": "Miłość niech będzie nieobłudna; miejcie w obrzydliwości złe; imając się dobrego. Miłością braterską jedni ku drugim skłonni bądźcie, uczciwością jedni drugich uprzedzając.",
    "1JN.4.10-11": "W tem jest miłość, nie iżbyśmy my umiłowali Boga, ale iż on umiłował nas i posłał Syna swego, aby był ubłaganiem za grzechy nasze. Najmilsi! ponieważ nas tak Bóg umiłował, i myśmy powinni jedni drugich miłować.",
    "EPH.4.2": "Ze wszelaką pokorą i cichością, i z nieskwapliwością, znosząc jedni drugich w miłości,",
    "PSA.86.15": "Ale ty, Panie, Boże miłosierny i litościwy, i nierychły ku gniewu, i wielce miłosierny, i prawdziwy!",
    "EXO.20.12": "Czcij ojca twego i matkę twoję, aby przedłużone były dni twoje na ziemi, którą Pan Bóg twój da tobie.",
    "PSA.127.3-5": "Oto dziatki są dziedzictwem od Pana, a płód żywota nagrodą. Jako strzały w ręku mocarza, tak są dziatki, które się darzą. Błogosławiony mąż, który niemi napełnił sajdak swój; nie będą zawstydzani, gdy się w bramie rozpierać będą z nieprzyjaciołmi swymi.",
    "EPH.6.1-3": "Dziatki! bądźcie posłuszne rodzicom waszym w Panu; boć to jest sprawiedliwa. Czcij ojca twego i matkę (toć jest pierwsze przykazanie z obietnicą). Aby ci się dobrze działo i abyś długo żył na ziemi.",
    "COL.3.20-21": "Dziatki! Posłuszne bądźcie rodzicom we wszystkiem; albowiem się to podoba Panu. Ojcowie! Nie pobudzajcie do gniewu dzieci waszych, aby serca nie traciły.",
    "PRO.17.6": "Korona starców są synowie synów ich, a ozdoba synów są ojcowie ich.",
    "PSA.103.17": "Ale miłosierdzie Pańskie od wieków aż na wieki nad tymi, którzy się go boją, a sprawiedliwość jego nad synami synów,",
    "DEU.6.6-7": "A będą te słowa, które ja dziś rozkazuję tobie, w sercu twojem; I będziesz je często przypominał synom twoim, i rozmawiał o nich siedząc w domu twym, i będąc w drodze, i kładąc się i wstawając.",
    "GEN.2.24": "Przetoż opuści człowiek ojca swego i matkę swoję, a przyłączy się do żony swojej, i będą jednem ciałem.",
    "PRO.31.28-29": "Powstawszy synowie jej błogosławią jej; także i mąż jej chwali ją, Mówiąc: Wiele niewiast grzecznie sobie poczynały; ale je ty przechodzisz wszystkie.",
    "EPH.5.25": "Mężowie! miłujcie żony wasze, jako i Chrystus umiłował kościół i wydał samego siebie za niego,",
    "1TI.5.8": "A jeźli kto o swoich, a najwięcej o domowych starania nie ma, wiary się zaprzał i gorszy jest niż niewierny.",
    "PSA.128.3": "Żona twoja będzie jako winna macica płodna po bokach domu twego; dziatki twoje jako latorośle oliwne około stołu twego.",
    "PRO.1.8-9": "Słuchaj, synu mój! ćwiczenia ojca twego, a nie opuszczaj nauki matki twojej. Bo to przyda wdzięczności głowie twojej, i będzie łańcuchem kosztownym szyi twojej.",
    "PSA.133.1": "Oto jako rzecz dobra, i jako wdzięczna, gdy bracia zgodnie mieszkają.",
    "PRO.20.7": "Sprawiedliwy chodzi w uprzejmości swojej; błogosławieni synowie jego po nim.",
    "ISA.54.13": "A wszyscy synowie twoi będą wyuczeni od Pana, i obfitość pokoju będą mieli synowie twoi.",
    "MAL.4.6": "Aby obrócił serca ojców ku synom, a serca synów ku ojcom ich, abym przyszedłszy ziemi przeklęstwem nie skarał.",
    "PRO.15.20": "Syn mądry uwesela ojca; ale głupi człowiek lekce waży matkę swoję.",
    "EPH.5.33": "A wszakże i każdy z was z osobna niechaj miłuje żonę swoję jako siebie samego, a żona niech się boi męża swego.",
    "PRO.23.24-25": "Bardzo się raduje ojciec sprawiedliwego, a kto spłodził mądrego, weseli się z niego. Niech się tedy weseli ojciec twój, i matka twoja; i niech się rozraduje rodzicielka twoja.",
    "GEN.18.19": "Znam go bowiem; przetoż przykaże synom swoim, i domowi swemu po sobie, aby strzegli drogi Pańskiej, i czynili sprawiedliwość i sąd; aby przywiódł Pan na Abrahama, co mu powiedział.",
    "PSA.68.6": "Bóg, który samotne w rodowite domy rozmnaża, wywodzi więźniów z oków; ale odporni mieszkać muszą w ziemi suchej.",
    "PRO.18.22": "Kto znalazł żonę, znalazł rzecz dobrą, i dostąpił łaski od Pana.",
    "COL.3.18-19": "Żony! Bądźcie poddane mężom swym, tak jako przystoi w Panu. Mężowie! Miłujcie żony wasze, a nie bądźcie surowymi przeciwko nim.",
    "PRO.6.20": "Strzeżże, synu mój! przykazania ojca twego, a nie opuszczaj nauki matki twojej.",
    "PRO.31.10": "Któż znajdzie niewiastę stateczną, gdyż nad perły daleko większa jest cena jej?",
    "ROM.5.1": "Będąc tedy usprawiedliwieni z wiary, pokój mamy z Bogiem przez Pana naszego Jezusa Chrystusa;",
    "COL.3.15": "A pokój Boży niech rząd prowadzi w sercach waszych, do któregoście też powołani w jedno ciało; a bądźcie wdzięcznymi.",
    "PSA.29.11": "Pan doda mocy ludowi swojemu; Pan będzie błogosławił ludowi swemu w pokoju.",
    "MAT.5.9": "Błogosławieni pokój czyniący; albowiem oni synami Bożymi nazwani będą.",
    "ROM.12.18": "Jeźli można, ile z was jest, ze wszystkimi ludźmi pokój miejcie.",
    "PSA.34.14": "Odwróć się od złego, a czyń dobrze; szukaj pokoju, a ścigaj go.",
    "PRO.16.7": "Gdy się podobają Panu drogi człowieka, i nieprzyjaciół jego do zgody z nim przywodzi.",
    "ISA.32.17": "I będzie pokój dzieło sprawiedliwości, a skutek sprawiedliwości odpocznienie i bezpieczność aż na wieki.",
    "PSA.119.165": "Pokój wielki dajesz tym, którzy miłują zakon twój, a nie doznawają żadnego obrażenia.",
    "ROM.14.17": "Albowiem królestwo Boże nie jest pokarm ani napój, ale sprawiedliwość i pokój i radość w Duchu Świętym:",
    "EPH.2.14": "Albowiem on jest pokojem naszym, który oboje jednem uczynił i średnią ścianę, która była przegrodą, rozwalił;",
    "PSA.85.8": "Ale posłucham, co rzecze Bóg, on Pan mocny; zaiste mówi pokój do ludu swego, i do świętych swoich, byle się jedno zaś do głupstwa nie wracali.",
    "JAS.3.18": "Ale owoc sprawiedliwości w pokoju bywa siany tym, którzy pokój czynią.",
    "HEB.12.14": "Pokoju naśladujcie ze wszystkimi i świętobliwości, bez której żaden nie ogląda Pana;",
    "ISA.55.12": "Przetoż w weselu wynijdziecie, a w pokoju doprowadzeni będziecie. Góry i pagórki chwałę przed wami głośno zaśpiewają, a wszystkie drzewa polne rękami klaskać będą.",
    "PSA.37.11": "Lecz pokorni odziedziczą ziemię, i rozkochają się w wielkości pokoju.",
    "1PE.3.11": "Niech się odwróci od złego, a czyni dobre; niech szuka pokoju i ściga go.",
    "ROM.8.6": "Gdyż zmysł ciała jest śmierć; ale zmysł ducha jest żywot i pokój,",
    "PSA.122.6-7": "Żądajcież pokoju Jeruzalemowi, mówiąc: Niech się szczęści tym, którzy cię miłują. Niech będzie pokój w basztach twoich, a uspokojenie w pałacach twoich.",
    "ISA.48.18": "Obyżeś był pilnował przykazania mego! byłby jako rzeka pokój twój, a sprawiedliwość twoja jako wały morskie;",
    "ISA.40.29": "Który dodaje spracowanemu siły, a tego, który nie ma żadnej siły, moc rozmnaża.",
    "PSA.46.1-2": "Bóg jest ucieczką i siłą naszą, ratunkiem we wszelkim ucisku najpewniejszym. Przetoż się bać nie będziemy, choćby się poruszyła ziemia, choćby się przeniosły góry w pośród morza;",
    "EPH.6.10": "Na ostatek, bracia moi! zmacniajcie się w Panu i w sile mocy jego;",
    "2CO.12.9-10": "Ale mi rzekł: Dosyć masz na łasce mojej; albowiem moc moja wykonywa się w słabości. Raczej się tedy więcej chlubić będę z krewkości moich, aby we mnie mieszkała moc Chrystusowa. Dlatego się kocham w krewkościach, w potwarzach, w niedostatkach, w prześladowaniach, i w uciskach dla Chrystusa; bo gdym jest słaby, tedym jest mocny.",
    "1CO.16.13": "Czujcież, stójcie w wierze, mężnie sobie poczynajcie, zmacniajcie się.",
    "PSA.118.14": "Pan jest mocą moją, i pieśnią moją; on był moim wybawicielem.",
    "PSA.138.3": "W dzień, któregom cię wzywał, wysłuchałeś mię, a posiliłeś mocą duszę moję.",
    "PSA.105.4": "Szukajcież Pana i mocy jego; szukajcie oblicza jego zawsze.",
    "PSA.119.28": "Rozpływa się od smutku dusza moja; utwierdźże mię według słowa twego.",
    "2SA.22.33": "Bóg jest mocą moją w wojsku, on czyni doskonałą drogę moję.",
    "PSA.59.17": "O mocy moja! tobie będę śpiewał; boś ty, Boże! twierdza moja, Bóg mój miłosierny.",
    "EPH.3.16": "Aby wam dał według bogactwa chwały swej, żebyście byli mocą utwierdzeni przez Ducha jego w wewnętrznym człowieku;",
    "ISA.66.13": "Jako ten, którego cieszy matka jego, tak Ja was cieszyć będę; a tak w Jeruzalemie uciechy miewać będziecie.",
    "MAT.5.4": "Błogosławieni, którzy się smęcą; albowiem pocieszeni będą.",
    "PSA.119.50": "Toć pociecha moja w utrapieniu mojem, że mię wyrok twój ożywia.",
    "ISA.40.1": "Cieszcie, cieszcie lud mój! mówi Bóg wasz.",
    "1PE.5.7": "Wszystko staranie wasze wrzuciwszy na niego, gdyż on ma pieczę o was.",
    "ISA.49.13": "Śpiewajcie niebiosa, rozraduj się ziemio, i głośno zabrzmijcie góry! albowiem Pan pocieszył lud swój, a nad ubogimi swoimi zmiłował się.",
    "PSA.119.76": "Niechajże mię, proszę, ucieszy miłosierdzie twoje według wyroku twego, któryś uczynił słudze twemu.",
    "ISA.51.12": "Ja, Jam jest pocieszyciel wasz. Któżeś ty, że się boisz człowieka śmiertelnego, i syna człowieczego trawie podobnego?",
    "PSA.9.9": "I będzie Pan ucieczką ubogiemu, ucieczką czasu ucisku.",
    "JHN.14.18": "Nie zostawię was sierotami, przyjdę do was.",
    "PSA.71.21": "Rozmnożysz dostojność moję a zasię ucieszysz mię.",
    "2TH.2.16-17": "A sam Pan nasz, Jezus Chrystus i Bóg a Ojciec nasz, który nas umiłował i dał pociechę wieczną, i nadzieję dobrą przez łaskę, Niech cieszy serca wasze i utwierdza was w każdej mowie i w uczynku dobrym.",
    "PSA.138.7": "Jeźlibym chodził w pośród utrapienia, ożywisz mię; przeciw popędliwości nieprzyjaciół moich wyciągniesz rękę twoję, a prawica twoja wyswobodzi mię.",
    "ISA.61.1-3": "Duch Panującego Pana jest nademną; przeto mię pomazał Pan, abym opowiadał Ewangeliję cichym, posłał mię, abym związał rany tych, którzy są skruszonego serca, abym zwiastował pojmanym wyzwolenie, a więźniom otworzenie ciemnicy; Abym ogłosił miłościwy rok Pański, i dzień pomsty Boga naszego; abym cieszył wszystkich płaczących; Abym sprawił radość płaczącym w Syonie, a dał im ozdobę miasto popiołu, olejek wesela miasto smutku, odzienie chwały miasto ściśnionego; i będą nazwani drzewami sprawiedliwości, szczepieniem Pańskiem, abym był uwielbiony.",
    "PRO.3.13-14": "Błogosławiony człowiek, który znajduje mądrość, i człowiek, który dostanie roztropności. Bo lepiej nią kupczyć, niżeli kupczyć srebrem: owszem pożyteczniejszy nad złoto dochód jej.",
    "PRO.9.10": "Początek mądrości jest bojaźń Pańska, a umiejętność świętych jest rozum.",
    "PSA.111.10": "Początek mądrości jest bojaźń Pańska; rozumu dobrego nabywają wszyscy, którzy rozkazanie Pańskie czyną; chwała jego trwa na wieki.",
    "PRO.4.7": "Początkiem wszystkiego jest mądrość, nabywajże mądrości, a za wzystkę majętność twoję nabywaj roztropności.",
    "ECC.7.12": "Albowiem pod cieniem mądrości, i pod cieniem srebra odpoczywa człowiek, a wszakże przedniejsza jest umiejętność mądrości; bo przynosi żywot tym, którzy ją mają.",
    "PRO.16.16": "Daleko lepiej jest nabyć mądrości, niżeli złota najczystszego; a nabyć roztropności lepiej, niż srebra.",
    "JAS.3.17": "Ale mądrość, która jest z góry, najprzódci jest czysta, potem spokojna, mierna, powolna, pełna miłosierdzia i owoców dobrych, nieposądzająca, i nieobłudna.",
    "PRO.11.2": "Za pychą przychodzi hańba; ale przy pokornych jest mądrość.",
    "PRO.12.15": "Droga głupiego zda się prosta przed oczyma jego; ale kto słucha rady, mądrym jest.",
    "PRO.19.20": "Słuchaj rady, a przyjmuj karność, abyś kiedyżkolwiek był mądrym.",
    "EPH.5.15-16": "Patrzajcie tedy, jakobyście ostrożnie chodzili, nie jako niemądrzy, ale jako mądrzy. Czas odkupując; bo dni złe są.",
    "PRO.15.22": "Gdzie niemasz rady, rozsypują się myśli; ale w mnóstwie radców ostoją się.",
    "PRO.13.20": "Kto chodzi z mądrymi, mądrym będzie; ale kto towarzyszy z głupimi, startym będzie.",
    "1CO.1.25": "Albowiem głupstwo Boże jest mędrsze niż ludzie; a mdłość Boża jest mocniejsza niż ludzie.",
    "PRO.18.15": "Serce rozumne nabywa umiejętności, a ucho mądrych szuka jej.",
    "PRO.24.3-4": "Mądrością bywa dom zbudowany, a roztropnością umocniony. Zaiste przez umiejętność komory napełnione bywają wszelakiemi bogactwami kosztownemi i wdzięcznemi.",
    "COL.2.2-3": "Aby pocieszone były serca ich, będąc spojone miłością, a to ku wszelkiemu bogactwu zupełnego i pewnego wyrozumienia, ku poznaniu tajemnicy Boga i Ojca, i Chrystusa, W którym skryte są wszystkie skarby mądrości i umiejętności.",
    "PRO.3.7": "Nie bądź mądrym sam u siebie; ale się bój Pana, a odstąp od złego.",
    "PSA.119.98-100": "Nad nieprzyjaciół moich mędrszym mię czynisz przykazaniem twojem; bo je mam ustawicznie przed sobą. Nad wszystkich nauczycieli moich stałem się rozumniejszym; bo świadectwa twoje są rozmyślaniem mojem. Nad starców jestem roztropniejszy; bo przykazań twoich przestrzegam.",
    "PRO.17.27-28": "Kto zawściąga mowy swe, jest umiejętnym; drogiego ducha jest mąż rozumny. Gdy głupi milczy, za mądrego poczytany bywa; a który zatula wargi swoje, za rozumnego.",
    "DAN.2.20-21": "A mówiąc Danijel rzekł: Niech będzie imię Boże błogosławione od wieku aż na wieki; albowiem mądrość i moc jego jest; On sam odmienia czasy i chwile; zrzuca królów i stanowi królów; daje mądrość mądrym, a umiejętnym rozum;",
    "PRO.14.29": "Nierychły do gniewu jest bogaty w rozum; ale porywczy pokazuje głupstwo.",
    "JOB.28.28": "Ale człowiekowi rzekł: Oto bojaźń Pańska jest mądrością, a warować się złego, jest rozumem.",
    "EPH.5.20": "Dzięki czyniąc zawsze za wszystko, w imieniu Pana naszego, Jezusa Chrystusa, Bogu i Ojcu.",
    "PHP.4.6": "Nie troszczcie się o żadną rzecz, ale we wszystkiem przez modlitwę i prośbę z dziękowaniem żądności wasze niech będą znajome u Boga.",
    "PSA.95.1-2": "Pójdźcież, śpiewajmy Panu; wykrzykujmy skale zbawienia naszego. Uprzedźmy oblicze jego z chwałą; psalmy mu śpiewajmy.",
    "PSA.9.1": "Będę wysławiał Pana ze wszystkiego serca mego; opowiadać będę wszysteki cuda twoje.",
    "HEB.13.15": "Przetoż przez niego ofiarujmy Bogu ofiarę chwały ustawicznie, to jest owoce warg wyznawających imieniowi jego.",
    "PSA.69.30": "Tedy będę chwalił imię Boże pieśnią, a będę je wielbił z dziękczynieniem.",
    "2CO.9.15": "Lecz Bogu niech będzie chwała za niewypowiedziany dar jego.",
    "PSA.106.1": "Halleluja. Wysławiajcie Pana; albowiem dobry, albowiem na wieki miłosierdzie jego.",
    "PSA.92.1-2": "Dobra rzecz jest wysławiać Pana, a śpiewać imieniowi twemu, o Najwyższy. Opowiadać z poranku miłosierdzie twoje, i prawdę twoję na każdą noc,",
    "1TI.4.4-5": "Bo wszelkie stworzenie Boże dobre jest, a nic nie ma być odrzuconem, co z dziękowaniem bywa przyjmowane; Albowiem poświęcone bywa przez słowo Boże i przez modlitwę.",
    "PSA.34.1": "Będę błogosławił Pana na każdy czas; zawżdy będzie chwała jego w ustach moich.",
    "DAN.2.23": "Ciebie ja, o Boże ojców moich! wysławiam i chwalę, żeś mi dał mądrość i moc, owszem, żeś mi teraz oznajmił to, o cośmy cię prosili; boś nam sen królewski oznajmił.",
    "COL.4.2": "W modlitwach trwajcie, czując w nich z dziękowaniem,",
    "PSA.118.28-29": "Tyś jest Bóg mój; przetoż cię wysławiać będę, Boże mój! wywyższać cię będę. Wysławiajcież Pana, albowiem jest dobry: albowiem na wieki miłosierdzie jego.",
    "ISA.12.4-5": "I rzeczecie dnia onego: Wysławiajcie Pana wzywajcie imienia jego, opowiadajcie między narodami sprawy jego, przypominajcie, że wysokie jest imię jego. Śpiewajcie Panu, albowiem wielkie rzeczy uczynił; niech to będzie wiadomo po wszystkiej ziemi.",
    "PSA.145.1-3": "Wywyższać cię będę, Boże mój, królu mój! i błogosławić będę imieniowi twemu na wieki wieków. Na każdy dzień błogosławić cię będę, a chwalić imię twoje na wieki wieków. Pan wielki jest i bardzo chwalebny, a wielkość jego nie może być dościgniona.",
    "1CO.15.57": "Ale niech będą Bogu dzięki, który nam dał zwycięstwo przez Pana naszego Jezusa Chrystusa.",
    "PSA.30.11-12": "Tedyś odmienił płacz mój w pląsanie; zdjąłeś ze mnie wór mój, a przepasałeś mię radością. Przetoż tobie śpiewać będzie chwała moja, a milczeć nie będzie. Panie, Boże mój! na wieki wysławiać cię będę.",
    "REV.7.12": "Mówiąc: Amen! Błogosławieństwo i chwała, i mądrość, i dziękowanie, i cześć, i moc, i siła Bogu naszemu na wieki wieków. Amen.",
    "PSA.103.12": "A jako daleko jest wschód od zachodu, tak daleko oddalił od nas przestępstwa nasze.",
    "COL.3.13": "Znaszając jedni drugich i odpuszczając sobie wzajemnie, jeźli ma kto przeciw komu skargę: jako i Chrystus odpuścił wam, tak i wy.",
    "MAT.6.14-15": "Bo jeźli odpuścicie ludziom upadki ich, odpuści i wam Ojciec wasz niebieski; A jeźli nie odpuścicie ludziom upadków ich, i Ojciec wasz nie odpuści wam upadków waszych.",
    "PSA.32.1-2": "Błogosławiony człowiek, któremu odpuszczono nieprawość, a którego zakryty jest grzech. Błogosławiony człowiek, któremu nie poczyta Pan nieprawości, a w którego duchu nie masz zdrady.",
    "LUK.6.37": "Nie sądźcie, a nie bądziecie sądzeni; nie potępiajcie, a nie będziecie potępieni, a będzie wam odpuszczono.",
    "ACT.3.19": "Przetoż pokutujcie, a nawróćcie się, aby były zgładzone grzechy wasze.",
    "HEB.8.12": "Bo miłościw będę nieprawościom ich, a grzechów ich i nieprawości ich nie wspomnę więcej.",
    "EPH.1.7": "W którym mamy odkupienie przez krew jego, to jest odpuszczenie grzechów, według bogactwa łaski jego,",
    "ISA.43.25": "Ja, Ja sam gładzę przestępstwa twoje dla siebie, a grzechów twoich nie wspomnę.",
    "MRK.11.25": "A gdy stoicie modląc się, odpuśćcież, jeźli co przeciw komu macie, aby i Ojciec wasz, który jest w niebiesiech, odpuścił wam upadki wasze.",
    "PSA.51.1-2": "Zmiłuj się nademną, Boże! według miłosierdzia twego; według wielkich litości twoich zgładź nieprawości moje. Omyj mię doskonale od nieprawości mojej, a od grzechu mego oczyść mię.",
    "LUK.23.34": "Tedy Jezus rzekł: Ojcze! odpuść im: boć nie wiedzą, co czynią. A rozdzieliwszy szaty jego, los o nie miotali.",
    "PSA.130.3-4": "Panie! będzieszli nieprawości upatrywał, Panie! któż się zostoi? Aleć u ciebie jest odpuszczenie, aby się ciebie bano.",
    "ROM.5.20": "A zakon przytem nastąpił, aby obfitował grzech; lecz gdzie się grzech rozmnożył, tam łaska tem więcej obfitowała.",
    "MAT.18.21-22": "Tedy przystąpiwszy do niego Piotr, rzekł: Panie! wielekroć zgrzeszy przeciwko mnie brat mój, a odpuszczę mu? czyż aż do siedmiu kroć? I rzekł mu Jezus: Nie mówię ci aż do siedmiu kroć, ale aż do siedmdziesiąt siedmiu kroć.",
    "HEB.4.16": "Przystąpmyż tedy z ufnością do tronu łaski, abyśmy dostąpili miłosierdzia i łaskę znaleźli ku pomocy czasu przygodnego.",
    "PRO.28.13": "Kto pokrywa przestępstwa swe, nie poszczęści mu się; ale kto je wyznaje i opuszcza, miłosierdzia dostąpi.",
    "ISA.55.7": "Niech opuści niepobożny drogę swoję, a człowiek nieprawy myśli swoje i niech się nawróci do Pana, a zmiłuje się; i do Boga naszego, gdyż jest hojnym w odpuszczaniu.",
    "DAN.9.9": "Ale Panu, Bogu naszemu, miłosierdzie i litość; ponieważeśmy mu odporni byli,",
    "1TH.5.17": "Bez przestanku się módlcie.",
    "MAT.6.6": "Ale ty, gdy się modlisz, wnijdź do komory swojej, a zawarłszy drzwi swoje, módl się Ojcu twemu, który jest w skrytości; a Ojciec twój, który widzi w skrytości, odda ci jawnie.",
    "ROM.8.26": "Także też i Duch dopomaga mdłościom naszym. Albowiem o co byśmy się modlić mieli, jako potrzeba, nie wiemy; ale tenże Duch przyczynia się za nami wzdychaniem niewymownem.",
    "MAT.6.9-10": "Wy tedy tak się módlcie; Ojcze nasz, któryś jest w niebiesiech! Święć się imię twoje; Przyjdź królestwo twoje; bądź wola twoja jako w niebie, tak i na ziemi.",
    "PSA.17.6": "Ja cię wzywam, bo mię wysłuchiwasz, Boże! Nakłoń ucha twego ku mnie, wysłuchaj słowa moje.",
    "LUK.11.9-10": "I jać wam powiadam: Proście, a będzie wam dano; szukajcie, a znajdziecie; kołaczcie, a będzie wam otworzono. Każdy bowiem, kto prosi, bierze, a kto szuka, znajduje, a temu, co kołacze, będzie otworzono.",
    "PSA.34.17": "Wołają sprawiedliwi, a Pan ich wysłuchiwa, i ze wszystkich trudności ich wybawia ich.",
    "EPH.6.18": "W każdej modlitwie i w prośbie modląc się na każdy czas w duchu, i około tego czując ze wszelką ustawicznością i z prośbą za wszystkich świętych,",
    "MAT.18.19-20": "Zasię powiadam wam: Iż gdyby się z was dwaj zgodzili na ziemi o wszelką rzecz, o którą by prosili, stanie się im od Ojca mego, który jest w niebiesiech. Albowiem gdzie są dwaj albo trzej zgromadzeni w imię moje, tam jestem w pośrodku ich.",
    "PSA.55.17": "W wieczór i rano, i w południe modlić się, i z trzaskiem wołać będę, aż wysłucha głos mój.",
    "PSA.66.19-20": "Aleć zaiste wysłuchał Bóg, a był pilen głosu modlitwy mojej. Błogosławiony Bóg, który nie odrzucił modlitwy mojej, ani odjął miłosierdzia swego odemnie.",
    "MAT.26.41": "Czujcież, a módlcie się, abyście nie weszli w pokuszenie; duchci jest ochotny, ale ciało mdłe.",
    "PSA.5.3": "Panie! rano usłysz głos mój; ranoć przedłożę modlitwę moję, i będę wyglądał pomocy.",
    "JHN.14.13-14": "A o cokolwiek prosić będziecie w imieniu mojem, to uczynię, aby był uwielbiony Ojciec w Synu. Jeźli o co będziecie prosić w imieniu mojem, ja uczynię.",
    "JHN.15.7": "Jeźli we mnie mieszkać będziecie i słowa moje w was mieszkać będą, czegobyściekolwiek chcieli, proście, a stanie się wam.",
    "PSA.141.2": "Niech będzie przyjemna modlitwa moja, jako kadzidło przed obliczem twoim, a podnoszenie rąk moich jako ofiara wieczorna.",
    "1TI.2.1-2": "Napominam tedy, aby przed wszystkiemi rzeczami czynione były prośby, modlitwy, przyczyny i dziękowania za wszystkich ludzi; Za królów i za wszystkich w przełożeństwie będących, abyśmy cichy i spokojny żywot wiedli we wszelkiej pobożności i uczciwości.",
    "LUK.18.1": "I powiedział im jeszcze podobieństwo do tego zmierzające, iż się zawsze potrzeba modlić, a nie ustawać,",
    "PSA.102.17": "Gdy wejrzy na modlitwę poniżonych, nie gardząc modlitwą ich.",
    "JHN.15.11": "Tomci wam powiedział, aby wesele moje w was trwało, a wesele wasze było zupełne.",
    "JAS.1.2-3": "Za największą radość miejcie, bracia moi! gdy w rozmaite pokusy wpadacie, Wiedząc, iż doświadczenie wiary waszej sprawuje cierpliwość;",
    "PSA.126.5-6": "Którzy siali ze łzami, żąć będą z wykrzykaniem; Tam i sam chodząc z płaczem rozsiewa lud drogie nasienie; ale zaś przyszedłszy z radością znosić będzie snopy swoje.",
    "1PE.1.8-9": "Którego nie widziawszy, miłujecie, którego teraz nie widząc, wszakże weń wierząc, weselicie się radością niewymowną i chwalebną, Odnosząc koniec wiary waszej: zbawienie dusz.",
    "PSA.5.11": "A niechaj się rozweselą wszyscy, co ufają w tobie; na wieki niech wykrzykują, gdyż ich ty szczycić będziesz, i rozradują się w tobie, którzy miłują imię twoje.",
    "JHN.16.22": "I wy teraz smutek macie; ale zasię ujrzę was, a będzie się radowało serce wasze, a radości waszej nikt nie odejmie od was.",
    "ISA.61.10": "Weseląc weselić się będą w Panu, a dusza moja rozraduje się w Bogu moim; bo mię oblókł w szaty zbawienia, a płaszczem sprawiedliwości przyodział mię, jako oblubieńca ozdobnego chwałą, i jako oblubienicę ozdobioną w klejnoty swoje.",
    "PSA.100.1-2": "Wykrzykajcie Panu, wszystka ziemio! Służcie Panu z weselem, przychodźcie przed oblicze jego z radością.",
    "PSA.32.11": "Weselcie się w Panu, i radujcie się sprawiedliwi, a wykrzykajcie wszyscy, którzyście serca szczerego.",
    "1TH.5.16": "Zawsze się radujcie.",
    "PSA.51.12": "Przywróć mi radość zbawienia twego, a duchem dobrowolnym podeprzyj mię.",
    "ISA.12.3": "I będziecie z radością czerpać wody ze zdrojów tegoż zbawienia.",
    "PSA.47.1": "Wszystkie narody klaskajcie rękoma, wykrzykajcie Bogu głosem wesela.",
    "LUK.15.10": "Tak, powiadam wam, będzie radość przed Anioły Bożymi nad jednym grzesznikiem pokutującym.",
    "PSA.97.11-12": "Światłości nasiano sprawiedliwemu, a radości tym, którzy są uprzejmego serca. Weselcie się sprawiedliwi w Panu, a wysławiajcie pamiątkę świętobliwości jego.",
    "JHN.16.24": "Dotąd o niceście nie prosili w imieniu mojem; proścież, a weźmiecie, aby radość wasza była doskonała."
};
